import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  Link,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  MenuItem,
  Select,
  Typography,
} from '@mui/material';
import { useEffect, useState } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { FixtureHistoryLibrary } from '../../data/Common/FixtureHistoryLibrary';
import { Fixture, FixtureLibrary } from '../../data/Common/FixtureLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ActionBus } from '../../utils/actions/ActionBus';
import { FixtureChangeAction } from '../../utils/actions/FixtureChangeAction';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { LogCategory, Logger } from '../../utils/Logger';
import { CNCViewType } from '../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';

interface FixtureSelectionDialogProps {
  open: boolean;
  onClose: () => void;
}

export function FixtureSelectionDialog({ open, onClose }: FixtureSelectionDialogProps) {
  const [selectedFixture, setSelectedFixture] = useState<Fixture | null>(null);
  const [selectedHistoryId, setSelectedHistoryId] = useState<string>('');

  const availableFixtures = FixtureLibrary.Instance.fixtures
    // Remove duplicates by fixture number (or name if number is empty)
    .filter((fixture, index, array) =>
      array.findIndex(f => {
        const key1 = f.fixtureNumber || f.name;
        const key2 = fixture.fixtureNumber || fixture.name;
        return key1 === key2;
      }) === index
    );

  const currentFixture = ConfigurationState.Instance.currentFixture;

  // Initialize selected fixture to current fixture when dialog opens
  useEffect(() => {
    if (open && currentFixture) {
      // Get fresh fixture list
      const availableFixtures = FixtureLibrary.Instance.fixtures
        .filter((fixture, index, array) =>
          array.findIndex(f => {
            const key1 = f.fixtureNumber || f.name;
            const key2 = fixture.fixtureNumber || fixture.name;
            return key1 === key2;
          }) === index
        );

      // Check if current fixture is in the available fixtures list
      const currentKey = currentFixture.fixtureNumber || currentFixture.name;
      const isCurrentFixtureAvailable = availableFixtures.some(
        fixture => (fixture.fixtureNumber || fixture.name) === currentKey
      );
      if (isCurrentFixtureAvailable) {
        setSelectedFixture(currentFixture);
      }
    }
  }, [open, currentFixture]);

  // Get fixture histories for the selected fixture
  const fixtureHistories = selectedFixture
    ? FixtureHistoryLibrary.Instance.getHistoriesForFixture(selectedFixture.fixtureNumber)
    : [];

  const handleHistoryChange = (event: any) => {
    setSelectedHistoryId(event.target.value);
  };

  const handleGoToXY = (fixture: Fixture) => {
    // Move tool tip to fixture XY position at current Z height
    const currentMachineZ = MachineStateData.Instance.currentMachinePoint.z;
    const fixtureXY = new CNCPoint(fixture.xOffset, fixture.yOffset, currentMachineZ, CoordinateType.MachineZero);

    // Calculate machine position where tool tip will be at fixture XY
    const targetPosition = CoordinateUtil.machinePositionForToolTipAtFixture(fixtureXY);
    const moveAction = MoveAction.fromCNCPoint(targetPosition, MoveType.Coordinates);
    ActionBus.Instance.addAction(moveAction);
  };

  const handleGoTo = (fixture: Fixture) => {
    // Move tool tip to fixture position
    const fixturePosition = new CNCPoint(fixture.xOffset, fixture.yOffset, fixture.zOffset, CoordinateType.MachineZero);

    // Calculate machine position where tool tip will be at fixture
    const targetPosition = CoordinateUtil.machinePositionForToolTipAtFixture(fixturePosition);

    // Debug logging
    Logger.Instance.log(LogCategory.UserInterface, `Go To fixture: ${fixture.name}`);
    Logger.Instance.log(LogCategory.UserInterface, `  Fixture position (MachineZero): ${fixture.xOffset}, ${fixture.yOffset}, ${fixture.zOffset}`);
    Logger.Instance.log(LogCategory.UserInterface, `  Target machine position: ${targetPosition.x}, ${targetPosition.y}, ${targetPosition.z}`);

    const moveAction = MoveAction.fromCNCPoint(targetPosition, MoveType.Coordinates);
    ActionBus.Instance.addAction(moveAction);
  };

  const handleRestore = async (fixture: Fixture) => {
    if (!selectedHistoryId) {
      UserMessageQueue.Instance.addMessage('❌ Please select a saved position to restore');
      return;
    }

    const history = FixtureHistoryLibrary.Instance.restoreFixturePosition(selectedHistoryId);
    if (!history) {
      UserMessageQueue.Instance.addMessage('❌ Failed to find saved position');
      return;
    }

    // Show confirmation dialog
    const confirmed = await ConfirmDialogManager.Instance.showConfirm({
      title: 'Restore Fixture Position',
      message: `Are you sure you want to change fixture ${fixture.fixtureNumber} to the saved position "${history.name}"?\n\nThis will update the fixture offsets to:\nX: ${history.xOffset}"\nY: ${history.yOffset}"\nZ: ${history.zOffset}"`,
      confirmText: 'Yes, Restore',
      severity: 'warning'
    });

    if (confirmed) {
      // Save current position to history before changing
      FixtureHistoryLibrary.Instance.saveFixturePosition(fixture);

      // Update fixture with historical position
      fixture.xOffset = history.xOffset;
      fixture.yOffset = history.yOffset;
      fixture.zOffset = history.zOffset;

      UserMessageQueue.Instance.addMessage(`✓ Restored fixture ${fixture.fixtureNumber} to "${history.name}"`);
    }
  };

  const handleUse = (fixture: Fixture) => {
    // Set this fixture as the current fixture using FixtureChangeAction
    const action = new FixtureChangeAction(fixture);
    ActionBus.Instance.addAction(action);
    // Note: Dialog stays open as requested
  };

  const handleClose = () => {
    setSelectedFixture(null);
    setSelectedHistoryId('');
    onClose();
  };

  const formatFixtureName = (fixture: Fixture) => {
    // If name and number are the same, only show the name
    if (fixture.name === fixture.fixtureNumber) {
      return fixture.name;
    }
    // Otherwise show name(number) format
    return `${fixture.name}(${fixture.fixtureNumber})`;
  };

  // Helper function to check if we're at a specific position (within tolerance)
  const isAtPosition = (x: number, y: number, z?: number) => {
    const currentPos = MachineStateData.Instance.currentMachinePoint;
    const tolerance = 0.001; // 0.001" tolerance

    const atXY = Math.abs(currentPos.x - x) < tolerance && Math.abs(currentPos.y - y) < tolerance;

    if (z !== undefined) {
      return atXY && Math.abs(currentPos.z - z) < tolerance;
    }

    return atXY;
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="xl"
      fullWidth
      PaperProps={{
        sx: { height: '80vh' }
      }}
    >
      <DialogTitle>Fixtures/Known Points</DialogTitle>
      <DialogContent sx={{ p: 2, height: '100%' }}>
        <Box sx={{ display: 'flex', height: '100%', gap: 2 }}>
          {/* Left side - Fixture controls and info */}
          <Box sx={{ width: '40%', display: 'flex', flexDirection: 'column', gap: 2 }}>

            {/* Fixture explanation */}
            <Box sx={{ p: 2, backgroundColor: ConfigurationData.Instance.lightTextColor, borderRadius: 1 }}>
              <Typography variant="h6" gutterBottom>
                About Fixtures
              </Typography>
              <Typography variant="body2" paragraph>
                A fixture is a reference point on your workpiece or machine that helps you position and orient your work accurately.
                Fixtures allow you to return to the same coordinate system for consistent machining operations.
              </Typography>
              <Link
                href="#"
                onClick={(e) => {
                  e.preventDefault();
                  // TODO: Open video in external browser or embedded player
                  window.open('https://example.com/fixture-video', '_blank');
                }}
                sx={{ textDecoration: 'underline' }}
              >
                Watch video: Understanding CNC Fixtures
              </Link>
            </Box>

            {/* Fixture Selection List */}
            <Box sx={{
              flex: 1,
              border: `1px solid ${ConfigurationData.Instance.borderColor}`,
              borderRadius: 1,
              overflow: 'hidden',
              display: 'flex',
              flexDirection: 'column'
            }}>
              <Typography variant="subtitle2" sx={{
                p: 1,
                backgroundColor: ConfigurationData.Instance.lightTextColor,
                borderBottom: `1px solid ${ConfigurationData.Instance.borderColor}`
              }}>
                Choose Fixture
              </Typography>
              <List sx={{
                flex: 1,
                overflow: 'auto',
                p: 0
              }}>
                {availableFixtures.map((fixture) => {
                  const fixtureKey = fixture.fixtureNumber || fixture.name;
                  const currentKey = currentFixture?.fixtureNumber || currentFixture?.name;
                  const isCurrent = fixtureKey === currentKey;
                  const isSelected = selectedFixture ? (selectedFixture.fixtureNumber || selectedFixture.name) === fixtureKey : false;

                  return (
                    <ListItem key={fixtureKey} disablePadding>
                      <ListItemButton
                        selected={isSelected}
                        onClick={() => {
                          setSelectedFixture(fixture);
                          setSelectedHistoryId('');
                        }}
                      >
                        <ListItemText
                          primary={formatFixtureName(fixture)}
                          primaryTypographyProps={{
                            sx: {
                              fontWeight: isCurrent ? 'bold' : 'normal',
                              fontSize: '0.95rem'
                            }
                          }}
                          secondary={isCurrent ? '(current)' : undefined}
                        />
                      </ListItemButton>
                    </ListItem>
                  );
                })}
              </List>
            </Box>

            {/* Action Buttons */}
            {selectedFixture && (
              <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', alignItems: 'center' }}>
                {/* Show message if already at fixture position */}
                {isAtPosition(selectedFixture.xOffset, selectedFixture.yOffset, selectedFixture.zOffset) ? (
                  <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                    ✓ Already at fixture position
                  </Typography>
                ) : (
                  <>
                    {/* Go To XY button */}
                    <Button
                      variant="outlined"
                      onClick={() => handleGoToXY(selectedFixture)}
                      sx={{ textTransform: 'none' }}
                    >
                      Go To XY
                    </Button>

                    {/* Go To button */}
                    <Button
                      variant="outlined"
                      onClick={() => handleGoTo(selectedFixture)}
                      sx={{ textTransform: 'none' }}
                    >
                      Go To
                    </Button>

                    {/* Only show Use button if fixture has a number (not a known point) and is not current fixture */}
                    {selectedFixture.fixtureNumber && selectedFixture.fixtureNumber !== currentFixture?.fixtureNumber && (
                      <Button
                        variant="contained"
                        onClick={() => handleUse(selectedFixture)}
                        sx={{ fontWeight: 'bold' }}
                      >
                        Use
                      </Button>
                    )}
                  </>
                )}
              </Box>
            )}

            {/* Restore Section - only show if fixture is selected and has history */}
            {selectedFixture && fixtureHistories.length > 0 && (
              <Box sx={{ p: 2, backgroundColor: ConfigurationData.Instance.lightTextColor, borderRadius: 1 }}>
                <Typography variant="h6" gutterBottom>
                  Restore Previous Position
                </Typography>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  Select a previously saved position from the dropdown and click Restore to change the fixture back to that saved position. We keep the last 5 saved positions for each fixture.
                </Typography>

                <FormControl fullWidth sx={{ mb: 2 }}>
                  <InputLabel>Saved Positions</InputLabel>
                  <Select
                    value={selectedHistoryId}
                    onChange={handleHistoryChange}
                    label="Saved Positions"
                  >
                    {fixtureHistories.map((history) => (
                      <MenuItem key={history.id} value={history.id}>
                        <Box>
                          <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                            {history.name}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            X{history.xOffset}" Y{history.yOffset}" Z{history.zOffset}" - {history.saveDate.toLocaleDateString()} {history.saveDate.toLocaleTimeString()}
                          </Typography>
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>

                {(() => {
                  // Check if selected history position matches current fixture position
                  const selectedHistory = fixtureHistories.find(h => h.id === selectedHistoryId);
                  const positionsMatch = selectedHistory &&
                    Math.abs(selectedHistory.xOffset - selectedFixture.xOffset) < 0.001 &&
                    Math.abs(selectedHistory.yOffset - selectedFixture.yOffset) < 0.001 &&
                    Math.abs(selectedHistory.zOffset - selectedFixture.zOffset) < 0.001;

                  if (positionsMatch) {
                    return (
                      <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                        ✓ Selected position matches current fixture location
                      </Typography>
                    );
                  }

                  return (
                    <Button
                      variant="outlined"
                      size="small"
                      onClick={() => handleRestore(selectedFixture)}
                      disabled={!selectedHistoryId}
                      sx={{ fontWeight: 'bold' }}
                    >
                      Restore Selected Position
                    </Button>
                  );
                })()}
              </Box>
            )}
          </Box>

          {/* Right side - 3D viewer only */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <FullSizeCNCViewer
              simulatorView={ConfigurationData.Instance.defaultView}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={MachineStateData.Instance.currentJob || Job.createTestJob()}
              enableOrbit={true}
              enableClampDragging={false}
              enableSpindleDrag={false}
              viewType={CNCViewType.Perspective}
            />
          </Box>
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} variant="contained">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}
