import { LineStyle as LineIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentLineNumberStep extends FlowStep {
    readonly __type = 'GetCurrentLineNumberStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Get Current Line Number';
    readonly description = 'Gets the current line number of executing program';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(LineIcon, { sx: { color: 'primary.main' } });
    }

    static readonly SUCCESS_PATH = 'success';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current line number');
            data.setVariable('currentLineNumber', 42);
            return GetCurrentLineNumberStep.SUCCESS_PATH;
        }

        try {
            const lineNumber = await Machine.getInstance().program.GetCurrentLineNumber();
            data.setVariable('currentLineNumber', lineNumber);
            //Logger.Instance.log(LogCategory.System, `Current line number: ${lineNumber}`);
            return GetCurrentLineNumberStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current line number failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('currentLineNumber', 0);
            return GetCurrentLineNumberStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentLineNumberStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const lineNumber = data.getVariable('currentLineNumber') as number || 0;
        return (
            <Typography variant="caption">
                Current line {lineNumber}: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






