import { Button, ButtonGroup, Card, CardContent } from '@mui/material';
import { FlowDataSelector } from '../components/Common/FlowDataSelector';
import { NumberInput } from '../components/Common/NumberInput';
import { ObserveState } from '../utils/statemanager/ObserveState';
import { FlowNumberValue, ValueSource } from './FlowNumberValue';
import { FlowStep } from './FlowStep';

interface FlowNumberValueEditorProps {
    numberValue: FlowNumberValue;
    flow: any;
    flowStep: FlowStep;
    label?: string;
}

/**
 * Component for editing a FlowNumberValue - allows selection between data element or direct value
 */
export function FlowNumberValueEditor({ numberValue, flow, flowStep, label }: FlowNumberValueEditorProps) {
    return (
        <ObserveState
            key={`flow-number-value-editor-${flowStep.id}`}
            listenTo={numberValue}
            properties={['valueSource', 'dataPath', 'numberValue']}
            control={() => (
                <Card variant="outlined">
                    <CardContent>
                        {/* Source Selection Buttons */}
                        <ButtonGroup fullWidth variant="outlined" sx={{ mb: 2 }}>
                            <Button
                                variant={numberValue.valueSource === ValueSource.DirectValue ? 'contained' : 'outlined'}
                                onClick={() => {
                                    numberValue.valueSource = ValueSource.DirectValue;
                                }}
                            >
                                Direct Value
                            </Button>
                            <Button
                                variant={numberValue.valueSource === ValueSource.DataElement ? 'contained' : 'outlined'}
                                onClick={() => {
                                    numberValue.valueSource = ValueSource.DataElement;
                                }}
                            >
                                Data Element
                            </Button>
                        </ButtonGroup>

                        {/* Value Input based on source */}
                        {numberValue.valueSource === ValueSource.DataElement ? (
                            <FlowDataSelector
                                flow={flow}
                                flowStep={flowStep}
                                allowedTypes={numberValue.getAllowedTypes()}
                                currentSelection={numberValue.dataPath ? [numberValue.dataPath] : []}
                                onChange={(paths) => {
                                    numberValue.dataPath = paths.length > 0 ? paths[0] : '';
                                }}
                                label={label || 'Select Data Element'}
                            />
                        ) : (
                            <NumberInput
                                label={label || 'Number Value'}
                                value={numberValue.numberValue}
                                onChange={(value) => {
                                    numberValue.numberValue = value;
                                }}
                                fullWidth
                            />
                        )}
                    </CardContent>
                </Card>
            )}
        />
    );
}
