import { Navigation as NavigationIcon } from '@mui/icons-material';
import { Box, FormControl, InputLabel, MenuItem, Select, TextField, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material';
import React, { useState } from 'react';
import { FlowPositionValueEditor } from '../../../../components/Common/FlowPositionValueEditor';
import { MovementCoordinateType } from '../../../../machine/ICNCMovement';
import { IOEvent } from '../../../../machine/IOEvent';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowPositionValue, ReferencePointType } from '../../../FlowPositionValue';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class MoveToUntilStep extends FlowStep {
    readonly __type = 'MoveToUntilStep';
    readonly category = ['Machine', 'Movement'];
    readonly name = 'Move To Until Event';
    readonly description = 'Moves to a position until a specific I/O event occurs';

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(NavigationIcon, { sx: { color: 'warning.main' } });
    }

    // Position calculation (reusable class)
    public positionValue: FlowPositionValue = new FlowPositionValue();

    // Event and speed parameters (specific to this step)
    public coordinateType: MovementCoordinateType = MovementCoordinateType.WorkZero;
    public event: IOEvent = IOEvent.XLimit;
    public xySpeed?: number;
    public zSpeed?: number;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return MoveToUntilStep.DONE_PATH;
        }

        try {
            const targetPoint = this.positionValue.calculateExecutionPoint(data);
            await Machine.getInstance().movement.MoveToUntil(targetPoint, this.coordinateType, this.event, this.xySpeed, this.zSpeed);
            return MoveToUntilStep.DONE_PATH;
        } catch (error) {
            console.error('MoveToUntil failed:', error);
            return MoveToUntilStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [MoveToUntilStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const targetPoint = this.positionValue.calculateExecutionPoint(data);
        return (
            <Typography variant="caption">
                Move to {targetPoint.x}, {targetPoint.y}, {targetPoint.z} until {this.event}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void, flow?: any, flowStep?: any }): React.ReactNode {
        function MoveToUntilEditUI() {
            const [event, setEvent] = useState((props.flowStep as MoveToUntilStep).event);
            const [xySpeed, setXySpeed] = useState((props.flowStep as MoveToUntilStep).xySpeed?.toString() || '');
            const [zSpeed, setZSpeed] = useState((props.flowStep as MoveToUntilStep).zSpeed?.toString() || '');

            React.useEffect(() => {
                (props.flowStep as MoveToUntilStep).event = event;
                (props.flowStep as MoveToUntilStep).xySpeed = xySpeed ? parseFloat(xySpeed) : undefined;
                (props.flowStep as MoveToUntilStep).zSpeed = zSpeed ? parseFloat(zSpeed) : undefined;
            }, [event, xySpeed, zSpeed]);

            return (
                <Box sx={{ minWidth: 400 }}>
                    {/* Position configuration */}
                    <FlowPositionValueEditor
                        positionValue={(props.flowStep as MoveToUntilStep).positionValue}
                        flow={props.flow}
                        flowStep={props.flowStep}
                    />

                    {/* Coordinate Type Selection */}
                    <Box sx={{ px: 2, pt: 2 }}>
                        <Typography variant="subtitle2" gutterBottom>
                            Coordinate Type
                        </Typography>
                        <ToggleButtonGroup
                            value={(props.flowStep as MoveToUntilStep).coordinateType}
                            exclusive
                            onChange={(e, newValue) => {
                                if (newValue !== null) {
                                    (props.flowStep as MoveToUntilStep).coordinateType = newValue;
                                }
                            }}
                            fullWidth
                            size="small"
                        >
                            <ToggleButton value={MovementCoordinateType.WorkZero}>
                                Work Zero
                            </ToggleButton>
                            <ToggleButton value={MovementCoordinateType.Machine}>
                                Machine
                            </ToggleButton>
                        </ToggleButtonGroup>
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                            Work Zero: Tool tip relative to fixture | Machine: Absolute machine coordinates
                        </Typography>
                    </Box>

                    {/* Event and Speed configuration */}
                    <Box sx={{ px: 2, pb: 2 }}>
                        <FormControl fullWidth margin="normal">
                            <InputLabel>Stop Event</InputLabel>
                            <Select
                                value={event}
                                label="Stop Event"
                                onChange={(e) => setEvent(e.target.value as IOEvent)}
                            >
                                <MenuItem value={IOEvent.XLimit}>X Limit Switch</MenuItem>
                                <MenuItem value={IOEvent.YLimit}>Y Limit Switch</MenuItem>
                                <MenuItem value={IOEvent.ZLimit}>Z Limit Switch</MenuItem>
                                <MenuItem value={IOEvent.ToolTouchPad}>Tool Touch Pad</MenuItem>
                                <MenuItem value={IOEvent.MaterialTouchPad}>Material Touch Pad</MenuItem>
                            </Select>
                        </FormControl>

                        <TextField
                            label="XY Speed (optional)"
                            type="number"
                            value={xySpeed}
                            onChange={(e) => setXySpeed(e.target.value)}
                            fullWidth
                            margin="normal"
                            helperText="Leave empty to use default speed"
                        />

                        <TextField
                            label="Z Speed (optional)"
                            type="number"
                            value={zSpeed}
                            onChange={(e) => setZSpeed(e.target.value)}
                            fullWidth
                            margin="normal"
                            helperText="Leave empty to use default speed"
                        />
                    </Box>
                </Box>
            );
        }

        return <MoveToUntilEditUI />;
    }

    public toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['positionValue']);
        return {
            ...baseData,
            __type: this.__type,
            positionValue: this.positionValue.toJSON()
        };
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['positionValue']);

        // Handle position value
        if (data.positionValue) {
            this.positionValue.fromJSON(data.positionValue);
        }

        // Migration: Handle old targetPoint format
        if (data.targetPoint && !data.positionValue) {
            // Old format had direct CNCPoint - set as work zero with offsets
            this.positionValue.setReferenceType(ReferencePointType.WorkHome);
            this.positionValue.setOffsetEnabled(true);
            this.positionValue.setXOffset(data.targetPoint.x || 0);
            this.positionValue.setYOffset(data.targetPoint.y || 0);
            this.positionValue.setZOffset(data.targetPoint.z || 0);
        }
    }
}