import { Refresh as ResetIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class ResetErrorStateStep extends FlowStep {
    readonly __type = 'ResetErrorStateStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Reset Error State';
    readonly description = 'Clears any error conditions on the machine';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ResetIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Reset error state');
            return ResetErrorStateStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().system.ResetErrorState();
            //Logger.Instance.log(LogCategory.System, 'Error state reset');
            return ResetErrorStateStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Reset error state failed:', error);
            return ResetErrorStateStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [ResetErrorStateStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Reset error state: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





