import { SkipNext as NextIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class StepRunNextStep extends FlowStep {
    readonly __type = 'StepRunNextStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Step Next';
    readonly description = 'Executes the next step in step-run mode';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(NextIcon, { sx: { color: 'primary.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Step to next command');
            return StepRunNextStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.StepRunNext();
            //Logger.Instance.log(LogCategory.System, 'Stepped to next command');
            return StepRunNextStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Step next failed:', error);
            return StepRunNextStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [StepRunNextStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Step next: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






