import {
  ChevronRight as ChevronRightIcon,
  ExpandMore as ExpandMoreIcon,
  Folder as FolderIcon,
  FolderOpen as FolderOpenIcon
} from '@mui/icons-material';
import {
  Box,
  Collapse,
  Dialog,
  DialogContent,
  DialogTitle,
  IconButton,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { FlowStepFactory } from '../../flow/FlowStepFactory';

interface StepInsertDialogProps {
  open: boolean;
  onClose: () => void;
  onInsertStep: (stepType: string) => void;
}

interface StepTypeInfo {
  type: string;
  name: string;
  category: string[];
  description: string;
  canAdd: boolean;
}

interface TreeNode {
  id: string;
  label: string;
  isStep: boolean;
  stepInfo?: StepTypeInfo;
  children: TreeNode[];
  path: string[];
}

// Helper function to count subcategories and steps in a tree node
const getNodeCounts = (node: TreeNode): { subcategories: number; steps: number } => {
  if (node.isStep) {
    return { subcategories: 0, steps: 1 };
  }

  let subcategories = 0;
  let steps = 0;

  for (const child of node.children) {
    if (child.isStep) {
      steps++;
    } else {
      subcategories++;
      const childCounts = getNodeCounts(child);
      subcategories += childCounts.subcategories;
      steps += childCounts.steps;
    }
  }

  return { subcategories, steps };
};

const TreeNodeComponent: React.FC<{
  node: TreeNode;
  onStepSelect: (stepType: string) => void;
  level: number;
}> = ({ node, onStepSelect, level }) => {
  const [expanded, setExpanded] = useState(true);

  const handleClick = () => {
    if (node.isStep && node.stepInfo) {
      onStepSelect(node.stepInfo.type);
    } else {
      setExpanded(!expanded);
    }
  };

  const indentSize = level * 20;

  // Get counts for this node
  const counts = !node.isStep ? getNodeCounts(node) : { subcategories: 0, steps: 0 };

  // Check if this category contains only steps (no subcategories)
  const hasOnlySteps = !node.isStep && node.children.every(child => child.isStep);

  return (
    <Box>
      {/* Category header */}
      {!node.isStep && (
        <Paper
          sx={{
            p: 1,
            ml: `${indentSize}px`,
            cursor: 'pointer',
            transition: 'all 0.2s',
            border: '1px solid transparent',
            bgcolor: 'grey.50',
            '&:hover': {
              borderColor: 'primary.main',
              bgcolor: 'grey.100',
            }
          }}
          onClick={handleClick}
        >
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <IconButton size="small" sx={{ p: 0.25 }}>
              {expanded ? <ExpandMoreIcon fontSize="small" /> : <ChevronRightIcon fontSize="small" />}
            </IconButton>

            {expanded ?
              <FolderOpenIcon sx={{ fontSize: 16, color: 'warning.main' }} /> :
              <FolderIcon sx={{ fontSize: 16, color: 'warning.main' }} />
            }

            <Typography variant="subtitle2" fontWeight="bold" noWrap sx={{ flex: 1 }}>
              {node.label}
            </Typography>

            {/* Display counts */}
            <Typography variant="caption" color="text.secondary" sx={{ ml: 1, fontSize: '0.7rem' }}>
              ({counts.subcategories > 0 && counts.steps > 0 ? `${counts.subcategories} categories, ${counts.steps} steps` :
                counts.subcategories > 0 ? `${counts.subcategories} categories` :
                  counts.steps > 0 ? `${counts.steps} steps` : '0'})
            </Typography>
          </Box>
        </Paper>
      )}

      {/* Children rendering */}
      {!node.isStep && (
        <Collapse in={expanded}>
          <Box sx={{ mt: 0.5 }}>
            {hasOnlySteps ? (
              // Render steps in a 3-column grid using their renderStepUI methods
              <Box sx={{
                display: 'grid',
                gridTemplateColumns: 'repeat(3, 1fr)',
                gap: 1.5,
                mt: 1,
                ml: '50px' // Indent steps 50px from the left
              }}>
                {node.children.map((stepNode) => {
                  if (!stepNode.stepInfo) return null;

                  // Create a temporary step instance to render its UI
                  const tempStep = FlowStepFactory.Instance.getStepByType(stepNode.stepInfo.type);
                  if (!tempStep) return null;

                  return (
                    <Paper
                      key={stepNode.id}
                      sx={{
                        p: 1.5,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        border: '1px solid',
                        borderColor: 'divider',
                        height: 80, // Fixed height for consistency
                        minWidth: 0, // Allow content to shrink
                        display: 'flex',
                        flexDirection: 'column',
                        justifyContent: 'space-between',
                        overflow: 'hidden', // Prevent content overflow
                        '&:hover': {
                          borderColor: 'primary.main',
                          bgcolor: 'primary.50',
                          transform: 'translateY(-2px)',
                          boxShadow: 2,
                        }
                      }}
                      onClick={() => onStepSelect(stepNode.stepInfo!.type)}
                    >
                      {/* Render the step using its own renderStepUI method */}
                      <Box sx={{
                        flex: 1,
                        display: 'flex',
                        alignItems: 'center',
                        minHeight: 0, // Allow shrinking
                        overflow: 'hidden'
                      }}>
                        {tempStep.renderStepUI()}
                      </Box>

                      {/* Add description tooltip */}
                      <Typography
                        variant="caption"
                        color="text.secondary"
                        sx={{
                          mt: 0.5,
                          fontSize: '0.65rem',
                          lineHeight: 1.1,
                          height: '2.2em', // Fixed height for 2 lines
                          overflow: 'hidden',
                          display: '-webkit-box',
                          WebkitLineClamp: 2,
                          WebkitBoxOrient: 'vertical',
                        }}
                        title={stepNode.stepInfo.description}
                      >
                        {stepNode.stepInfo.description}
                      </Typography>
                    </Paper>
                  );
                })}
              </Box>
            ) : (
              // Render subcategories in tree format
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                {node.children.map((child) => (
                  <TreeNodeComponent
                    key={child.id}
                    node={child}
                    onStepSelect={onStepSelect}
                    level={level + 1}
                  />
                ))}
              </Box>
            )}
          </Box>
        </Collapse>
      )}
    </Box>
  );
};

export const StepInsertDialog: React.FC<StepInsertDialogProps> = ({
  open,
  onClose,
  onInsertStep,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [treeRoot, setTreeRoot] = useState<TreeNode | null>(null);

  // Build tree structure from step categories
  const buildTree = (steps: StepTypeInfo[]): TreeNode => {
    const root: TreeNode = {
      id: 'root',
      label: 'All Steps',
      isStep: false,
      children: [],
      path: []
    };

    const nodeMap = new Map<string, TreeNode>();
    nodeMap.set('', root);

    steps.forEach(step => {
      let currentPath = '';
      let currentNode = root;

      // Create category nodes
      step.category.forEach((categoryPart, index) => {
        const newPath = currentPath ? `${currentPath}/${categoryPart}` : categoryPart;

        if (!nodeMap.has(newPath)) {
          const categoryNode: TreeNode = {
            id: newPath,
            label: categoryPart,
            isStep: false,
            children: [],
            path: step.category.slice(0, index + 1)
          };

          nodeMap.set(newPath, categoryNode);
          currentNode.children.push(categoryNode);
        }

        currentNode = nodeMap.get(newPath)!;
        currentPath = newPath;
      });

      // Add step node
      const stepNode: TreeNode = {
        id: step.type,
        label: step.name,
        isStep: true,
        stepInfo: step,
        children: [],
        path: [...step.category, step.name]
      };

      currentNode.children.push(stepNode);
    });

    // Sort children recursively
    const sortNodes = (node: TreeNode) => {
      node.children.sort((a, b) => {
        // Categories first, then steps
        if (a.isStep !== b.isStep) {
          return a.isStep ? 1 : -1;
        }
        return a.label.localeCompare(b.label);
      });

      node.children.forEach(sortNodes);
    };

    sortNodes(root);
    return root;
  };
  useEffect(() => {
    if (open) {
      // Load available step types using the factory
      try {
        const factory = FlowStepFactory.Instance;
        const stepTypes = factory.getAllStepTypes();
        const stepInfos: StepTypeInfo[] = stepTypes
          .map((type: string) => {
            const tempStep = factory.getStepByType(type);
            if (!tempStep) {
              return null;
            }
            const info = {
              type,
              name: tempStep.name || type,
              category: tempStep.category,
              description: tempStep.description || '',
              canAdd: tempStep.canAdd
            };
            return info;
          })
          .filter((stepInfo): stepInfo is StepTypeInfo => stepInfo !== null)
          .filter(stepInfo => stepInfo.canAdd); // Only include steps that can be added
        setTreeRoot(buildTree(stepInfos));
      } catch (error) {
        setTreeRoot(null);
      }
      setSearchTerm('');
    }
  }, [open]);

  // Filter tree based on search term
  const filterTree = (node: TreeNode, searchTerm: string): TreeNode | null => {
    if (!searchTerm) return node;

    const lowerSearch = searchTerm.toLowerCase();

    // If this is a step node, check if it matches
    if (node.isStep) {
      const matches = node.label.toLowerCase().includes(lowerSearch) ||
        (node.stepInfo?.description.toLowerCase().includes(lowerSearch) ?? false);
      return matches ? node : null;
    }

    // For category nodes, recursively filter children
    const filteredChildren = node.children
      .map(child => filterTree(child, searchTerm))
      .filter(child => child !== null) as TreeNode[];

    // Include category if it has matching children or if category name matches
    if (filteredChildren.length > 0 || node.label.toLowerCase().includes(lowerSearch)) {
      return {
        ...node,
        children: filteredChildren
      };
    }

    return null;
  };

  const filteredTree = treeRoot && searchTerm ?
    filterTree(treeRoot, searchTerm) :
    treeRoot;

  const handleStepClick = (stepType: string) => {
    onInsertStep(stepType);
    onClose();
  };

  const handleClose = () => {
    setSearchTerm('');
    onClose();
  }; return (
    <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth sx={{ '& .MuiDialog-paper': { height: '75vh', maxHeight: '75vh' } }}>
      <DialogTitle sx={{ pb: 1 }}>Add Step</DialogTitle>
      <DialogContent sx={{ pb: 2, display: 'flex', flexDirection: 'column', height: '100%' }}>
        <TextField
          fullWidth
          placeholder="Search steps and categories..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          variant="outlined"
          size="small"
          sx={{ mb: 2, flexShrink: 0 }}
        />

        <Box sx={{ flex: 1, overflow: 'auto', minHeight: 0, pr: '10px' }}>
          {filteredTree ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
              {filteredTree.children.map((child) => (
                <TreeNodeComponent
                  key={child.id}
                  node={child}
                  onStepSelect={handleStepClick}
                  level={0}
                />
              ))}
            </Box>
          ) : (
            <Typography variant="body2" color="text.secondary" textAlign="center" sx={{ py: 4 }}>
              Loading step types...
            </Typography>
          )}
        </Box>

        {filteredTree && filteredTree.children.length === 0 && searchTerm && (
          <Typography variant="body2" color="text.secondary" textAlign="center" sx={{ py: 4 }}>
            No steps found matching "{searchTerm}"
          </Typography>
        )}
      </DialogContent>
    </Dialog>
  );
};
