import React from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  List,
  ListItemText,
  ListItemIcon,
  ListItemButton,
  Box,
  Typography,
  Chip,
  IconButton
} from '@mui/material';
import {
  Description as FileIcon,
  AccessTime as TimeIcon,
  Close as CloseIcon
} from '@mui/icons-material';
import { JobStorage, JobType } from '../../../data/JobStorage';

export interface RecentJobsDialogProps {
  open: boolean;
  onClose: () => void;
  onJobSelect: (job: any) => void;
}

export function RecentJobsDialog({ open, onClose, onJobSelect }: RecentJobsDialogProps) {
  // Get all recent jobs (not limited to 5)
  const recentJobs = JobStorage.Instance.getRecentJobs(JobType.Milling);

  const handleJobSelect = (job: any) => {
    onJobSelect(job);
    onClose();
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="md" 
      fullWidth
      PaperProps={{
        sx: { height: '80vh' }
      }}
    >
      <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Typography variant="h6">Recent Jobs</Typography>
        <IconButton onClick={onClose} size="small">
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      
      <DialogContent dividers>
        {recentJobs.length === 0 ? (
          <Box 
            sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              minHeight: 200
            }}
          >
            <Typography variant="body2" color="text.secondary">
              No recent jobs found
            </Typography>
          </Box>
        ) : (
          <List>
            {recentJobs.map((job, index) => (
              <ListItemButton 
                key={index}
                sx={{ 
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: 'divider',
                  mb: 1,
                  '&:hover': {
                    borderColor: 'primary.main',
                  }
                }}
                onClick={() => handleJobSelect(job)}
              >
                <ListItemIcon>
                  <FileIcon />
                </ListItemIcon>
                <ListItemText 
                  primary={job.name} 
                  secondary={
                    <Box>
                      <Typography variant="caption" component="div">
                        {job.material.name} - {job.material.xLength}" × {job.material.yLength}" × {job.material.height}"
                      </Typography>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                        <TimeIcon fontSize="small" />
                        <Typography variant="caption">Variable time</Typography>
                        <Chip 
                          label={job.material.type} 
                          size="small" 
                          variant="outlined"
                          sx={{ height: 16, fontSize: '0.6rem' }}
                        />
                      </Box>
                    </Box>
                  }
                />
              </ListItemButton>
            ))}
          </List>
        )}
      </DialogContent>
      
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  );
}
