import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Link,
  Grid,
  Divider,
  IconButton,
} from '@mui/material';
import {
  TouchApp as TouchIcon,
  Hardware as MachineIcon,
  Home as HomeIcon,
  Build as ToolIcon,
  PlayArrow as RunIcon,
  AccountTree as FlowIcon,
  Star as StarIcon,
  StarBorder as StarBorderIcon,
} from '@mui/icons-material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { UserActionData } from '../../data/UserActionData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { UserActionRegistry, DefaultUserActions, type IUserAction } from '../../utils/userActions';
import { QuickActions } from '../Common/QuickActions';

interface ActionsPanelProps {
  onViewChange?: (view: string) => void;
}

interface ActionLinkProps {
  action: IUserAction;
  onClick: (actionId: string) => void;
  showUsageCount?: boolean;
}

const ActionLink: React.FC<ActionLinkProps> = ({
  action,
  onClick,
  showUsageCount = false
}) => {
  const Icon = action.icon;
  const [isHovering, setIsHovering] = useState(false);
  const userActionData = UserActionData.Instance;
  const isFavorite = userActionData.isFavorite(action.id);
  const usageStats = showUsageCount ? userActionData.getActionUsage(action.id) : undefined;
  
  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    userActionData.toggleFavorite(action.id);
  };
  
  return (
    <Box
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
      sx={{
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        width: '100%',
      }}
    >
      <Link
        component="button"
        variant="body2"
        onClick={() => onClick(action.id)}
        disabled={action.enabled === false}
        sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 1.5,
          py: 1,
          px: 0,
          pr: isHovering || isFavorite ? 4 : 0, // Make room for star
          textDecoration: 'none',
          color: action.enabled === false ? 'text.disabled' : 'text.primary',
          cursor: action.enabled === false ? 'not-allowed' : 'pointer',
          borderRadius: 1,
          '&:hover': {
            backgroundColor: action.enabled === false ? 'transparent' : 'action.hover',
            textDecoration: 'none',
          },
          background: 'none',
          border: 'none',
          textAlign: 'left',
          width: '100%',
          transition: 'background-color 0.2s, padding-right 0.2s',
        }}
      >
        <Icon sx={{ 
          fontSize: 18, 
          color: action.enabled === false ? 'text.disabled' : 'primary.main' 
        }} />
        <Box sx={{ flex: 1 }}>
          <Typography variant="body2" sx={{ 
            color: 'inherit',
            fontWeight: 500,
          }}>
            {action.name}
            {usageStats && (
              <Typography component="span" variant="body2" sx={{ 
                color: 'text.secondary',
                fontWeight: 400,
                ml: 0.5
              }}>
                ({usageStats.count})
              </Typography>
            )}
          </Typography>
        </Box>
      </Link>
      
      {/* Star icon - shows on hover or if favorited */}
      {(isHovering || isFavorite) && (
        <IconButton
          size="small"
          onClick={handleFavoriteClick}
          sx={{
            position: 'absolute',
            right: 0,
            top: '50%',
            transform: 'translateY(-50%)',
            padding: 0.5,
            transition: 'all 0.2s',
            '&:hover': {
              backgroundColor: 'action.hover',
              transform: 'translateY(-50%) scale(1.1)',
            },
          }}
        >
          {isFavorite ? (
            <StarIcon sx={{ 
              fontSize: 16, 
              color: 'warning.main' // Gold color for favorites
            }} />
          ) : (
            <StarBorderIcon sx={{ 
              fontSize: 16, 
              color: 'text.secondary',
              '&:hover': { color: 'warning.main' }
            }} />
          )}
        </IconButton>
      )}
    </Box>
  );
};

const ActionSection: React.FC<{
  title: string;
  icon: React.ComponentType<any>;
  actions: IUserAction[];
  onActionClick: (actionId: string) => void;
  showUsageCount?: boolean;
}> = ({ title, icon: Icon, actions, onActionClick, showUsageCount = false }) => (
  <Card 
    variant="outlined" 
    sx={{ 
      mb: 0, 
      height: 'fit-content',
      transition: 'box-shadow 0.2s',
      '&:hover': { 
        boxShadow: 3,
        borderColor: 'primary.light'
      }
    }}
  >
    <CardContent sx={{ p: 2.5, '&:last-child': { pb: 2.5 } }}>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 1.5 }}>
        <Icon sx={{ mr: 1.5, color: 'primary.main', fontSize: 22 }} />
        <Typography variant="h6" sx={{ 
          fontWeight: 600, 
          fontSize: '16px',
          color: 'text.primary'
        }}>
          {title}
        </Typography>
      </Box>
      <Divider sx={{ mb: 1.5 }} />
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25 }}>
        {actions.map((action) => (
          <ActionLink
            key={action.id}
            action={action}
            onClick={onActionClick}
            showUsageCount={showUsageCount}
          />
        ))}
      </Box>
    </CardContent>
  </Card>
);

export function ActionsPanel({ onViewChange }: ActionsPanelProps) {
  const registry = UserActionRegistry.Instance;
  const [actionsInitialized, setActionsInitialized] = useState(false);

  // Re-initialize with view change callback and check if actions are available
  React.useEffect(() => {
    // Re-initialize with the view change callback (actions may already be registered)
    DefaultUserActions.initialize(onViewChange);
    
    // Check if actions are available
    const checkActions = () => {
      const actionCount = registry.getAllActions().length;
      if (actionCount > 0) {
        setActionsInitialized(true);
      }
    };
    
    // Check immediately
    checkActions();
    
    // If not initialized, check again after a brief delay
    if (!actionsInitialized) {
      const timeout = setTimeout(checkActions, 100);
      return () => clearTimeout(timeout);
    }
  }, [onViewChange, registry, actionsInitialized]);

  const handleActionClick = async (actionId: string) => {
    try {
      await registry.executeAction(actionId);
      // Record that this action was used
      UserActionData.Instance.recordActionUsage(actionId);
    } catch (error) {
      console.error('Failed to execute action:', error);
    }
  };

  const getCategoryIcon = (category: string): React.ComponentType<any> => {
    const iconMap: { [key: string]: React.ComponentType<any> } = {
      'Run Job': RunIcon,
      'Measure Z': TouchIcon,
      'Machine Homing': HomeIcon,
      'Machine Controls': MachineIcon,
      'Tool Management': ToolIcon,
      'Custom Routines': FlowIcon,
    };
    return iconMap[category] || ToolIcon;
  };

  return (
    <ObserveState
      listenTo={[ConfigurationData.Instance, UserActionData.Instance]}
      properties={['systemConfigurationUnlocked', 'favoriteActionIds', 'actionUsageStats']}
      control={() => {
        // Don't render until actions are initialized
        if (!actionsInitialized) {
          return (
            <Box sx={{ p: 2, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Loading actions...
              </Typography>
            </Box>
          );
        }

        const actionsByCategory = registry.getActionsByCategories();
        // //console.log('Rendering actions panel, categories:', actionsByCategory.size);

        return (
          <Box sx={{ p: 2, height: '100%', overflow: 'auto' }}>
            {actionsByCategory.size === 0 && (
              <Card variant="outlined" sx={{ p: 3, textAlign: 'center' }}>
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                  No actions available
                </Typography>
              </Card>
            )}

            {/* Quick Actions Component - Favorite and Popular Actions */}
            <QuickActions onViewChange={onViewChange} showSeeAllLink={false} />

            {/* Divider between special sections and regular sections */}
            <Divider sx={{ my: 1.5 }} />

            {/* Regular Category Sections - Two Column Stacked Layout */}
            <Grid container spacing={1}>
              <Grid item xs={12} md={6}>
                {/* Left Column Stack */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                  {Array.from(actionsByCategory.entries())
                    .filter((_, index) => index % 2 === 0)
                    .map(([category, actions]) => (
                      <ActionSection
                        key={category}
                        title={category}
                        icon={getCategoryIcon(category)}
                        actions={actions}
                        onActionClick={handleActionClick}
                      />
                    ))}
                </Box>
              </Grid>
              <Grid item xs={12} md={6}>
                {/* Right Column Stack */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                  {Array.from(actionsByCategory.entries())
                    .filter((_, index) => index % 2 === 1)
                    .map(([category, actions]) => (
                      <ActionSection
                        key={category}
                        title={category}
                        icon={getCategoryIcon(category)}
                        actions={actions}
                        onActionClick={handleActionClick}
                      />
                    ))}
                </Box>
              </Grid>
            </Grid>
          </Box>
        );
      }}
    />
  );
}
