import { Stop as StopIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class StopStep extends FlowStep {
    readonly __type = 'StopStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Stop Program';
    readonly description = 'Stops the currently running program';

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(StopIcon, { sx: { color: 'error.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return StopStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.Stop();
            return StopStep.DONE_PATH;
        } catch (error) {
            console.error('Stop failed:', error);
            return StopStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [StopStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Stop program: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Stop Program</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step stops the currently running program execution.
                    This is a controlled stop, different from an emergency stop.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle2" gutterBottom>Effect:</Typography>
                    <Typography variant="body2" sx={{ color: 'error.main' }}>
                        • Stops current program execution
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'error.main' }}>
                        • Maintains current position
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'error.main' }}>
                        • Program can be resumed later if needed
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}