import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { MachineStateData } from '../data/MachineStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { ActionBus } from './actions/ActionBus';
import { MoveAction, MoveType } from './actions/MoveAction';
import { CoordinateUtil } from './CoordinateUtil';
import { LogCategory, Logger } from './Logger';

/**
 * Utility class for coordinate setting and movement operations
 * Shared between JogControls and Home page
 */
export class CoordinateOperations {
    /**
     * Set work zero for a specific axis so that the current tool tip position becomes 0
     * @param axis The axis to set work zero for ('X', 'Y', 'Z', or 'A')
     */
    public static setWorkZero(axis: string): void {
        const machineState = MachineStateData.Instance;
        const currentMachinePos = machineState.currentMachinePoint;
        const currentWorkZero = machineState.currentWorkZero;

        // Get current work coordinates (tool tip position)
        const currentWorkCoords = CoordinateUtil.toWorkZero(currentMachinePos);

        // To make current tool tip position become 0, we need to adjust currentWorkZero
        // by the current work coordinate value
        // Formula: newWorkZero = currentWorkZero + currentWorkCoords
        let newWorkZero: CNCPoint;
        switch (axis.toUpperCase()) {
            case 'X':
                newWorkZero = new CNCPoint(
                    currentWorkZero.x + currentWorkCoords.x,
                    currentWorkZero.y,
                    currentWorkZero.z,
                    CoordinateType.MachineZero
                );
                break;
            case 'Y':
                newWorkZero = new CNCPoint(
                    currentWorkZero.x,
                    currentWorkZero.y + currentWorkCoords.y,
                    currentWorkZero.z,
                    CoordinateType.MachineZero
                );
                break;
            case 'Z':
                newWorkZero = new CNCPoint(
                    currentWorkZero.x,
                    currentWorkZero.y,
                    currentWorkZero.z + currentWorkCoords.z,
                    CoordinateType.MachineZero
                );
                break;
            case 'A':
                // A-axis placeholder - for now just keep current work zero
                newWorkZero = currentWorkZero;
                Logger.Instance.log(LogCategory.Coordinates, 'A-axis work zero setting not yet implemented');
                break;
            default:
                Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                return;
        }

        // Update the machine state
        machineState.currentWorkZero = newWorkZero;

        Logger.Instance.log(LogCategory.Coordinates, `Set work zero for ${axis} axis`);
        UserMessageQueue.Instance.addMessage(`✓ Set ${axis} work zero`);
    }

    /**
     * Move to a specific position on a single axis
     * @param axis The axis to move ('X', 'Y', 'Z', or 'A')
     * @param targetValue The target value in work coordinates
     * @param isAbsolute Whether to use absolute (machine) coordinates or work coordinates
     */
    public static moveToPosition(axis: string, targetValue: number, isAbsolute: boolean = false): void {
        const machineState = MachineStateData.Instance;

        if (isNaN(targetValue)) {
            Logger.Instance.logError(LogCategory.Coordinates, `Invalid target value: ${targetValue}`);
            return;
        }

        const currentPos = machineState.currentMachinePoint;

        if (isAbsolute) {
            // In machine coordinate mode, create machine coordinate point directly
            let newMachinePosition: CNCPoint;
            switch (axis.toUpperCase()) {
                case 'X':
                    newMachinePosition = new CNCPoint(targetValue, currentPos.y, currentPos.z, CoordinateType.MachineZero);
                    break;
                case 'Y':
                    newMachinePosition = new CNCPoint(currentPos.x, targetValue, currentPos.z, CoordinateType.MachineZero);
                    break;
                case 'Z':
                    newMachinePosition = new CNCPoint(currentPos.x, currentPos.y, targetValue, CoordinateType.MachineZero);
                    break;
                case 'A':
                    // A-axis placeholder - for now just keep current position
                    newMachinePosition = new CNCPoint(currentPos.x, currentPos.y, currentPos.z, CoordinateType.MachineZero);
                    Logger.Instance.log(LogCategory.Coordinates, 'A-axis movement not yet implemented');
                    break;
                default:
                    Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                    return;
            }

            // Update the machine state using MoveAction and ActionBus
            const moveAction = MoveAction.fromCNCPoint(newMachinePosition, MoveType.Coordinates);
            ActionBus.Instance.addAction(moveAction);

            Logger.Instance.log(LogCategory.Coordinates, `Moving to machine coordinate ${axis}=${targetValue}`);
            return;
        }

        // Work coordinate mode
        const currentWorkPos = CoordinateUtil.toWorkZero(currentPos);

        // Create new work coordinate point with the target value for this axis
        let newWorkPosition: CNCPoint;
        switch (axis.toUpperCase()) {
            case 'X':
                newWorkPosition = new CNCPoint(targetValue, currentWorkPos.y, currentWorkPos.z, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'Y':
                newWorkPosition = new CNCPoint(currentWorkPos.x, targetValue, currentWorkPos.z, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'Z':
                newWorkPosition = new CNCPoint(currentWorkPos.x, currentWorkPos.y, targetValue, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'A':
                // A-axis placeholder - for now just keep current position
                newWorkPosition = new CNCPoint(currentWorkPos.x, currentWorkPos.y, currentWorkPos.z, CoordinateType.WorkZeroWithOffsets);
                Logger.Instance.log(LogCategory.Coordinates, 'A-axis movement not yet implemented');
                break;
            default:
                Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                return;
        }

        // Convert WorkZeroWithOffsets coordinate to machine coordinate using CoordinateUtil
        const newMachinePosition = CoordinateUtil.toMachineZero(newWorkPosition);

        // Update the machine state using MoveAction and ActionBus
        const moveAction = MoveAction.fromCNCPoint(newMachinePosition, MoveType.Coordinates);
        ActionBus.Instance.addAction(moveAction);

        Logger.Instance.log(LogCategory.Coordinates, `Moving to work coordinate ${axis}=${targetValue}`);
    }

    /**
     * Move to work home position (0,0,0)
     */
    public static moveToWorkHome(): void {
        const workHomePosition = new CNCPoint(0, 0, 0, CoordinateType.WorkZeroWithOffsets);
        const machinePosition = CoordinateUtil.toMachineZero(workHomePosition);
        const moveAction = MoveAction.fromCNCPoint(machinePosition, MoveType.Coordinates);
        ActionBus.Instance.addAction(moveAction);

        Logger.Instance.log(LogCategory.Coordinates, 'Moving to work home (0,0,0)');
        UserMessageQueue.Instance.addMessage('📍 Moving to work home');
    }

    /**
     * Move to machine home position
     */
    public static moveToMachineHome(): void {
        const machineHomePosition = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
        const moveAction = MoveAction.fromCNCPoint(machineHomePosition, MoveType.Coordinates);
        ActionBus.Instance.addAction(moveAction);

        Logger.Instance.log(LogCategory.Coordinates, 'Moving to machine home (0,0,0)');
        UserMessageQueue.Instance.addMessage('📍 Moving to machine home');
    }

    /**
     * Set all axes to work zero
     */
    public static setAllAxesToWorkZero(): void {
        this.setWorkZero('X');
        this.setWorkZero('Y');
        this.setWorkZero('Z');
        UserMessageQueue.Instance.addMessage('✓ Set all axes to work zero');
    }

    /**
     * Get current work coordinate for a specific axis
     * @param axis The axis to get the coordinate for ('X', 'Y', 'Z', or 'A')
     * @returns The work coordinate value
     */
    public static getWorkCoordinate(axis: string): number {
        const machineState = MachineStateData.Instance;
        const machinePoint = machineState.currentMachinePoint;

        // Use CoordinateUtil to properly convert machine coordinates to work coordinates
        const workPoint = CoordinateUtil.toWorkZero(machinePoint);

        switch (axis.toUpperCase()) {
            case 'X':
                return workPoint.x;
            case 'Y':
                return workPoint.y;
            case 'Z':
                return workPoint.z;
            case 'A':
                // A-axis not yet implemented in CNCPoint
                Logger.Instance.log(LogCategory.Coordinates, 'A-axis not yet implemented');
                return 0;
            default:
                Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                return 0;
        }
    }

    /**
     * Get current machine coordinate for a specific axis
     * @param axis The axis to get the coordinate for ('X', 'Y', 'Z', or 'A')
     * @returns The machine coordinate value
     */
    public static getMachineCoordinate(axis: string): number {
        const machineState = MachineStateData.Instance;
        const machinePoint = machineState.currentMachinePoint;

        switch (axis.toUpperCase()) {
            case 'X':
                return machinePoint.x;
            case 'Y':
                return machinePoint.y;
            case 'Z':
                return machinePoint.z;
            case 'A':
                // A-axis not yet implemented in CNCPoint
                Logger.Instance.log(LogCategory.Coordinates, 'A-axis not yet implemented');
                return 0;
            default:
                Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                return 0;
        }
    }

    /**
     * Get the coordinate value to display for a specific axis
     * If there's a proposed position (user typing), shows that value
     * Otherwise shows the current position
     * @param axis The axis to get the coordinate for ('X', 'Y', 'Z', or 'A')
     * @returns The coordinate value to display in work coordinates
     */
    public static getDisplayCoordinate(axis: string): number {
        const machineState = MachineStateData.Instance;
        const proposedPosition = machineState.proposedSpindlePosition;

        // If there's a proposed position, show it in work coordinates
        if (proposedPosition) {
            const proposedWork = CoordinateUtil.toWorkZero(proposedPosition);
            switch (axis.toUpperCase()) {
                case 'X':
                    return proposedWork.x;
                case 'Y':
                    return proposedWork.y;
                case 'Z':
                    return proposedWork.z;
                case 'A':
                    return 0; // A-axis placeholder
                default:
                    return 0;
            }
        }

        // Otherwise show current work coordinate
        return this.getWorkCoordinate(axis);
    }

    /**
     * Check if there's a proposed position different from current position for a specific axis
     * Used to determine if coordinate display should be highlighted
     * @param axis The axis to check ('X', 'Y', 'Z', or 'A')
     * @returns true if the proposed position differs from current for this axis
     */
    public static hasProposedPositionForAxis(axis: string): boolean {
        const machineState = MachineStateData.Instance;
        const proposedPosition = machineState.proposedSpindlePosition;

        if (!proposedPosition) {
            return false;
        }

        // Compare proposed vs current in work coordinates
        const currentPos = machineState.currentMachinePoint;
        const proposedWork = CoordinateUtil.toWorkZero(proposedPosition);
        const currentWork = CoordinateUtil.toWorkZero(currentPos);

        const tolerance = 0.001;

        switch (axis.toUpperCase()) {
            case 'X':
                return Math.abs(proposedWork.x - currentWork.x) > tolerance;
            case 'Y':
                return Math.abs(proposedWork.y - currentWork.y) > tolerance;
            case 'Z':
                return Math.abs(proposedWork.z - currentWork.z) > tolerance;
            case 'A':
                return false; // A-axis not implemented yet
            default:
                return false;
        }
    }

    /**
     * Update the proposed spindle position for a specific axis
     * If a proposed position already exists, preserve other axis values
     * @param axis The axis to update ('X', 'Y', 'Z', or 'A')
     * @param value The new value in work coordinates
     */
    public static setProposedCoordinate(axis: string, value: number): void {
        const machineState = MachineStateData.Instance;

        // Use existing proposed position if it exists, otherwise use current position
        const basePos = machineState.proposedSpindlePosition || machineState.currentMachinePoint;
        const workPos = CoordinateUtil.toWorkZero(basePos);

        // Create new work coordinate point with the entered value
        let newWorkPoint: CNCPoint;
        switch (axis.toUpperCase()) {
            case 'X':
                newWorkPoint = new CNCPoint(value, workPos.y, workPos.z, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'Y':
                newWorkPoint = new CNCPoint(workPos.x, value, workPos.z, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'Z':
                newWorkPoint = new CNCPoint(workPos.x, workPos.y, value, CoordinateType.WorkZeroWithOffsets);
                break;
            case 'A':
                newWorkPoint = new CNCPoint(workPos.x, workPos.y, workPos.z, CoordinateType.WorkZeroWithOffsets);
                Logger.Instance.log(LogCategory.Coordinates, 'A-axis not yet implemented');
                break;
            default:
                Logger.Instance.logError(LogCategory.Coordinates, `Invalid axis: ${axis}`);
                return;
        }

        // Convert to machine coordinates and set as proposed position
        const machinePoint = CoordinateUtil.toMachineZero(newWorkPoint);
        machineState.proposedSpindlePosition = machinePoint;
    }
}
