import {
  Add, // Used as UploadIcon
  Article,
  // Machine and Tools
  Build,
  Cancel, // Used as LayersIcon

  // Status and Feedback
  CheckCircle,
  ChevronLeft,
  ChevronRight,
  Clear,
  Close, // Used as OpenIcon
  CloudUpload, // Used as machine icon
  Construction,
  Delete,
  Download,
  Edit,
  Emergency,
  ExpandMore,
  FilterList,
  Fullscreen,
  FullscreenExit, // Used as ClampIcon
  Hardware,
  // Navigation and Layout
  Home, // Used as 3D viewer settings icon

  // Specific Usage
  HomeWork, // Used as ClampIcon in some places
  Inventory, // Used as SwapIcon
  Layers,
  Link, // Used for callable flow steps

  // File and Data
  OpenInNew, // Used as MDI icon

  // Colors and Design
  Palette,
  Pause,
  // Actions - Primary
  PlayArrow, // Used as UnhomeIcon

  // Input/Output States
  RadioButtonChecked, // Used for closed/active circuit states
  RadioButtonUnchecked,
  Refresh,
  Save,
  Settings,
  Stop, // Used as MaterialIcon
  SwapHoriz, // Used as TouchIcon
  Terminal, // Used as logs icon

  // Communication
  TouchApp, // Used as ColorIcon

  // 3D and Visualization
  Tune,
  // Actions - Secondary  
  Upload,
  // Visibility
  Visibility,
  VisibilityOff,
  Warning,
} from '@mui/icons-material';
import React from 'react';

/**
 * Centralized icon management for the HavenCNC application
 * This class provides static methods to access all icons used throughout the system
 * Makes it easy to replace or customize icons in one central location
 */
export class SystemIcons {

  // =============================================================================
  // NAVIGATION AND LAYOUT ICONS
  // =============================================================================

  static get home() { return <Home />; }
  static get settings() { return <Settings />; }
  static get mdi() { return <Terminal />; }
  static get fullscreen() { return <Fullscreen />; }
  static get fullscreenExit() { return <FullscreenExit />; }
  static get chevronRight() { return <ChevronRight />; }
  static get chevronLeft() { return <ChevronLeft />; }
  static get expandMore() { return <ExpandMore />; }

  // =============================================================================
  // PRIMARY ACTION ICONS
  // =============================================================================

  static get play() { return <PlayArrow />; }
  static get pause() { return <Pause />; }
  static get stop() { return <Stop />; }
  static get emergency() { return <Emergency />; }
  static get add() { return <Add />; }
  static get edit() { return <Edit />; }
  static get delete() { return <Delete />; }
  static get save() { return <Save />; }
  static get close() { return <Close />; }
  static get cancel() { return <Cancel />; }

  // =============================================================================
  // SECONDARY ACTION ICONS
  // =============================================================================

  static get upload() { return <Upload />; }
  static get cloudUpload() { return <CloudUpload />; }
  static get download() { return <Download />; }
  static get refresh() { return <Refresh />; }
  static get clear() { return <Clear />; }
  static get filter() { return <FilterList />; }

  // =============================================================================
  // MACHINE AND MANUFACTURING ICONS
  // =============================================================================

  static get machine() { return <Hardware />; }
  static get tool() { return <Build />; }
  static get clamp() { return <Construction />; }
  static get material() { return <Inventory />; }
  static get layers() { return <Layers />; }
  static get swap() { return <SwapHoriz />; }

  // =============================================================================
  // STATUS AND FEEDBACK ICONS
  // =============================================================================

  static get success() { return <CheckCircle />; }
  static get check() { return <CheckCircle />; }
  static get warning() { return <Warning />; }

  // =============================================================================
  // VISIBILITY AND DISPLAY ICONS
  // =============================================================================

  static get show() { return <Visibility />; }
  static get hide() { return <VisibilityOff />; }
  static get visible() { return <Visibility />; }
  static get invisible() { return <VisibilityOff />; }

  // =============================================================================
  // FILE AND DATA ICONS
  // =============================================================================

  static get openExternal() { return <OpenInNew />; }
  static get logs() { return <Article />; }

  // =============================================================================
  // UI ELEMENT ICONS
  // =============================================================================

  static get color() { return <Palette />; }
  static get viewerSettings() { return <Tune />; }
  static get callableAsStep() { return <Link />; }

  // =============================================================================
  // INPUT/OUTPUT STATE ICONS
  // =============================================================================

  static get inputClosed() { return <RadioButtonChecked sx={{ color: '#4caf50' }} />; } // Green for closed circuit
  static get inputOpen() { return <RadioButtonUnchecked sx={{ color: '#9e9e9e' }} />; } // Gray for open circuit
  static get outputActive() { return <CheckCircle sx={{ color: '#4caf50' }} />; } // Green checkmark for active
  static get outputInactive() { return <Cancel sx={{ color: '#f44336' }} />; } // Red X for inactive

  // =============================================================================
  // INTERACTION ICONS
  // =============================================================================

  static get touch() { return <TouchApp />; }

  // =============================================================================
  // SPECIALIZED USAGE ICONS
  // =============================================================================

  static get unhome() { return <HomeWork />; }

  // =============================================================================
  // ICON VARIATION METHODS
  // =============================================================================

  /**
   * Get an icon with specific props (size, color, etc.)
   */
  static withProps(iconMethod: () => React.ReactElement, props: any) {
    const IconComponent = iconMethod().type;
    return <IconComponent {...props} />;
  }

  /**
   * Get all icons as a categorized object for inventory purposes
   */
  static getAllIcons() {
    return {
      'Navigation & Layout': {
        home: this.home,
        settings: this.settings,
        fullscreen: this.fullscreen,
        fullscreenExit: this.fullscreenExit,
        chevronRight: this.chevronRight,
        chevronLeft: this.chevronLeft,
        expandMore: this.expandMore,
      },
      'Primary Actions': {
        play: this.play,
        pause: this.pause,
        stop: this.stop,
        emergency: this.emergency,
        add: this.add,
        edit: this.edit,
        delete: this.delete,
        save: this.save,
        close: this.close,
        cancel: this.cancel,
      },
      'Secondary Actions': {
        upload: this.upload,
        cloudUpload: this.cloudUpload,
        download: this.download,
        refresh: this.refresh,
        clear: this.clear,
        filter: this.filter,
      },
      'Machine & Manufacturing': {
        machine: this.machine,
        tool: this.tool,
        clamp: this.clamp,
        material: this.material,
        layers: this.layers,
        swap: this.swap,
      },
      'Status & Feedback': {
        success: this.success,
        check: this.check,
        warning: this.warning,
      },
      'Visibility & Display': {
        show: this.show,
        hide: this.hide,
        visible: this.visible,
        invisible: this.invisible,
      },
      'File & Data': {
        openExternal: this.openExternal,
      },
      'UI Elements': {
        color: this.color,
        viewerSettings: this.viewerSettings,
      },
      'Input/Output States': {
        inputClosed: this.inputClosed,
        inputOpen: this.inputOpen,
        outputActive: this.outputActive,
        outputInactive: this.outputInactive,
      },
      'Interaction': {
        touch: this.touch,
      },
      'Specialized Usage': {
        unhome: this.unhome,
      },
    };
  }

  /**
   * Get usage information for each icon
   */
  static getIconUsage(): Record<string, string[]> {
    return {
      home: ['Navigation', 'Homing actions', 'Home page', 'StartupLayer', 'LeftNavigation'],
      settings: ['Configuration tabs', 'Settings panels', 'Machine setup', 'SystemConfigurationTab'],
      fullscreen: ['HavenCNCLayout fullscreen toggle'],
      fullscreenExit: ['HavenCNCLayout exit fullscreen'],
      chevronRight: ['HavenCNCLayout panel navigation'],
      chevronLeft: ['HavenCNCLayout panel navigation'],
      expandMore: ['Accordion expansions', 'MachineDataTab', 'Settings sections'],
      play: ['Job execution', 'Spindle start', 'Process start', 'RunStage', 'WarmUpSpindleStep'],
      pause: ['Job pause', 'Process pause', 'RunStage'],
      stop: ['Job stop', 'Emergency stop', 'Process termination', 'RunStage', 'HomingProgressStep'],
      emergency: ['Emergency stop button', 'Critical alerts', 'ControlPanel', 'RunStage'],
      add: ['Add new items', 'Create buttons', 'Plus actions', 'ConfigurationTab', 'Library tabs'],
      edit: ['Edit existing items', 'Modify actions', 'Configuration', 'ControlPanel', 'Library tabs'],
      delete: ['Remove items', 'Delete actions', 'Clear operations', 'ConfigurationTab', 'Library tabs'],
      save: ['Save configurations', 'Export data', 'Persist changes', 'ConfigurationTab', 'MaterialEditor'],
      close: ['Close dialogs', 'Cancel operations', 'Exit views', 'MaterialEditor', 'WorkpieceEditor'],
      cancel: ['Cancel operations', 'HomingProgressStep'],
      upload: ['Upload files', 'MachineDataTab export'],
      cloudUpload: ['Cloud upload', 'GCodeStage file upload'],
      download: ['Download files', 'MachineDataTab import'],
      refresh: ['Refresh data', 'ConfigurationTab reset', 'LogViewerTab'],
      clear: ['Clear data', 'ClampTopViewEditor', 'LogViewerTab'],
      filter: ['Filter lists', 'LogViewerTab'],
      machine: ['Machine configuration', 'Hardware settings'],
      tool: ['Tool management', 'CNC tools', 'Manufacturing', 'ControlPanel'],
      clamp: ['Workholding', 'Clamp management', 'Fixture setup', 'ControlPanel', 'ClampEditorForm'],
      material: ['Material selection', 'Stock management', 'Workpiece', 'MaterialEditor', 'MaterialStage'],
      layers: ['Layer management', 'DefaultUserActions', 'MachineControl'],
      swap: ['Swap tools', 'Exchange operations', 'ToolStage'],
      success: ['Completion status', 'Success messages', 'Check marks', 'Wizard steps'],
      check: ['Check marks', 'Success indicators', 'Wizard completion'],
      warning: ['Alerts', 'Caution messages', 'Status warnings', 'ConfirmDialog', 'HomingPreparationStep'],
      show: ['Show elements', 'Visibility toggle', 'CNCViewerDemo'],
      hide: ['Hide elements', 'Visibility toggle', 'CNCViewerDemo'],
      visible: ['Visibility controls', 'SystemConfigurationTab'],
      invisible: ['Hide visibility', 'SystemConfigurationTab'],
      openExternal: ['Open external links', 'Home component'],
      color: ['Color selection', 'Palette actions', 'WorkpieceEditor'],
      viewerSettings: ['3D viewer configuration', 'Simulator settings', 'CNCViewer'],
      touch: ['Touch operations', 'TouchApp actions', 'ActionsPanel'],
      unhome: ['Unhome machine', 'DefaultUserActions'],
    };
  }
}
