import { Build as ToolIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentToolNumberStep extends FlowStep {
    readonly __type = 'GetCurrentToolNumberStep';
    readonly category = ['Machine', 'Features'];
    readonly name = 'Get Current Tool Number';
    readonly description = 'Gets the currently loaded tool number';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ToolIcon, { sx: { color: 'primary.main' } });
    }

    static readonly SUCCESS_PATH = 'success';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current tool number');
            data.setVariable('currentToolNumber', 1);
            return GetCurrentToolNumberStep.SUCCESS_PATH;
        }

        try {
            const toolNumber = await Machine.getInstance().features.GetCurrentToolNumber();
            data.setVariable('currentToolNumber', toolNumber);
            //Logger.Instance.log(LogCategory.System, `Current tool number: ${toolNumber}`);
            return GetCurrentToolNumberStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current tool number failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('currentToolNumber', 0);
            return GetCurrentToolNumberStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentToolNumberStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const toolNumber = data.getVariable('currentToolNumber') as number || 0;
        return (
            <Typography variant="caption">
                Current tool #{toolNumber}: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






