import React, { ReactNode } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { Machine, MovementCoordinateType } from '../../machine/Machine';
import { CollisionAction, CollisionDetection, CollisionResult } from '../CollisionDetection';
import { CollisionModalManager } from '../CollisionModalManager';
import { LogCategory, Logger } from '../Logger';
import { ObserveState } from '../statemanager/ObserveState';
import { StateManager } from '../statemanager/StateManager';
import { ActionBus, IAction } from './ActionBus';
import { combineCoordinates, createTargetPosition, getMoveDelayTime, MoveType, resolveCoordinates } from './MoveActionUtils';

// Re-export MoveType for backwards compatibility
export { MoveType } from './MoveActionUtils';

export class MoveAction implements IAction {
    public type = 'Move';
    public id: string = `move-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`; // Unique ID
    public singleAction = true; // Only one move action allowed in queue at a time
    public x: number; // Always resolved in constructor
    public y: number; // Always resolved in constructor
    public z: number; // Always resolved in constructor
    public a?: number; // A-axis can remain optional
    public startingPoint: CNCPoint;
    public moveType: MoveType;
    public noDelay: boolean = false;
    public _timeoutId?: number; // Made public for combining logic
    public _startTime: number = Date.now(); // Made public for combining logic

    // Collision handling
    public bypassCollisionDetection: boolean = false;
    public isShowingCollisionWarning: boolean = false; // Track if this action is showing collision UI

    constructor(coordinateType: CoordinateType, x?: number, y?: number, z?: number, a?: number, moveType: MoveType = MoveType.Coordinates, bypassCollisionDetection: boolean = false, noDelay: boolean = false) {
        // Capture the starting point (current machine position) when the action is created
        this.startingPoint = MachineStateData.Instance.currentMachinePoint;
        this.moveType = moveType;
        this.noDelay = noDelay;
        this.bypassCollisionDetection = bypassCollisionDetection;

        // Get the base position for resolving undefined coordinates
        // Use proposed spindle position if it exists (for chained moves), otherwise current machine position
        const machineState = MachineStateData.Instance;
        const basePos = machineState.proposedSpindlePosition || machineState.currentMachinePoint;

        // Use extracted utility function to resolve coordinates
        const resolved = resolveCoordinates(coordinateType, x, y, z, a, basePos);
        this.x = resolved.x;
        this.y = resolved.y;
        this.z = resolved.z;
        this.a = resolved.a;
    }

    canCombine(other: IAction): boolean {
        if (!(other instanceof MoveAction)) {
            return false; // Cannot combine with non-MoveAction
        }
        return true; // Can combine with other MoveActions
    }

    combineWith(other: IAction): IAction {
        if (other instanceof MoveAction) {
            // Cancel this existing action's timeout to prevent it from executing
            if (this._timeoutId) {
                clearTimeout(this._timeoutId);
                this._timeoutId = undefined;
            }

            // Clear collision warning flag since we're combining with new action
            this.isShowingCollisionWarning = false;

            // Use extracted utility function to combine coordinates
            const combined = combineCoordinates(this, other);

            // Create the combined action with MachineZero coordinates
            const combinedAction = new MoveAction(
                CoordinateType.MachineZero,
                combined.x,
                combined.y,
                combined.z,
                combined.a,
                other.moveType, // Use the new action's move type
                this.bypassCollisionDetection || other.bypassCollisionDetection, // Bypass if either action bypasses
                other.noDelay // Use the new action's no delay setting
            );

            // Preserve the original starting point from this existing action
            combinedAction.startingPoint = this.startingPoint;

            // Reset the start time to now so the timer restarts at 2 seconds
            // This gives the user a fresh countdown when they click the jog button again
            const now = Date.now();
            combinedAction._startTime = now;

            // Update the spindle drag position to the new target immediately
            // This allows subsequent jog operations to build on the combined target
            const newTarget = createTargetPosition(combined.x, combined.y, combined.z);

            MachineStateData.Instance.proposedSpindlePosition = newTarget;

            return combinedAction;
        }
        throw new Error('Cannot combine with non-MoveAction');
    }

    /**
     * Get the delay time for this move type
     */
    public getDelayTime(): number {
        return getMoveDelayTime(this.moveType, ConfigurationData.Instance);
    }

    /**
     * Render UI for this action - countdown timer with cancel button
     */
    renderUI(): ReactNode {
        // Don't show countdown UI if this action is showing collision warning
        if (this.isShowingCollisionWarning) {
            return null; // Modal manager handles collision UI
        }

        // Check safe mode overrides for delay UI
        const configState = ConfigurationState.Instance;
        const shouldSkipDelayUI = this.noDelay || configState.delayOff;

        // Don't show countdown UI if noDelay is enabled or delay override is active
        if (shouldSkipDelayUI) {
            return null;
        }

        // Show normal move UI countdown
        const delayTime = this.getDelayTime();
        if (delayTime <= 0) return null; // No UI if no delay

        return (
            <MoveActionUI
                key={this.id}
                action={this}
                delayTime={delayTime}
                startTime={this._startTime}
            />
        );
    }

    /**
     * Cancel this move action
     */
    cancel(): void {
        // Clear collision warning flag
        this.isShowingCollisionWarning = false;

        // Clear timeout if it exists
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        // Clear the proposed spindle position since the action is being canceled
        MachineStateData.Instance.proposedSpindlePosition = null;

        // Remove this action from the action bus
        ActionBus.Instance.completeAction(this);
    }

    /**
     * Execute the move action
     */
    async execute(): Promise<void> {
        // Get the target position first
        const targetPosition = this.getTargetPosition();

        // Skip collision detection if bypassing is enabled via constructor flag
        if (this.bypassCollisionDetection) {
            this.executeMove(targetPosition);
            return;
        }

        // Check for collisions before executing the move
        const currentPosition = MachineStateData.Instance.currentMachinePoint;
        const collisionInputs = await CollisionDetection.createInputsFromMachineState(MachineStateData.Instance);
        const collisionResult = CollisionDetection.checkMoveCollision(currentPosition, targetPosition, collisionInputs);

        if (collisionResult.hasCollision) {
            // Get collision options for the UI
            const options = CollisionDetection.getCollisionOptions(collisionResult);

            // Show collision warning UI and DO NOT execute the move
            // The move will only execute when user responds with their choice
            await this.showCollisionWarning(collisionResult, options, targetPosition);
            return; // STOP HERE - don't execute until user responds
        }

        // No collision detected, proceed with normal execution
        this.executeMove(targetPosition);
    }

    /**
     * Execute the move with the given target position
     */
    private executeMove(targetPosition: CNCPoint): void {
        const delayTime = this.getDelayTime();

        // Set the proposed spindle position to show intermediate position during move
        MachineStateData.Instance.proposedSpindlePosition = targetPosition;

        // Check safe mode overrides for delay
        const configState = ConfigurationState.Instance;
        const shouldSkipDelay = this.noDelay || configState.delayOff;

        // Skip delay if noDelay is enabled or delay override is active
        if (delayTime > 0 && !shouldSkipDelay) {
            // Set up delayed execution - action should already be in ActionBus if needed
            this._timeoutId = window.setTimeout(async () => {
                await this.executeImmediate(targetPosition);
                // Remove from action bus when complete
                ActionBus.Instance.completeAction(this);

                // Force cleanup any stale actions after a delay
                setTimeout(() => {
                    ActionBus.Instance.forceCleanup();
                }, 200);
            }, delayTime);
        } else {
            // Execute immediately if no delay or noDelay is enabled
            this.executeImmediate(targetPosition);
        }
    }

    /**
     * Show collision warning UI and handle user response
     */
    private async showCollisionWarning(collisionResult: CollisionResult, options: Array<{
        action: CollisionAction;
        label: string;
        description: string;
        point?: CNCPoint;
    }>, targetPosition: CNCPoint): Promise<void> {
        // Set flag to prevent renderUI from showing countdown
        this.isShowingCollisionWarning = true;

        // IMPORTANT: Cancel any pending execution timeout
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        // Create collision inputs for debug information
        const machineState = MachineStateData.Instance;
        const collisionInputs = await CollisionDetection.createInputsFromMachineState(machineState);

        // Show the collision warning modal using the modal manager
        CollisionModalManager.Instance.showCollisionWarning(
            collisionResult,
            options,
            (action: CollisionAction, safePosition?: CNCPoint) => {
                this.handleCollisionResponse(action, safePosition);
            },
            targetPosition,
            this.startingPoint,
            collisionInputs
        );
    }

    /**
     * Handle user's collision warning response
     */
    public handleCollisionResponse(action: CollisionAction, safePosition?: CNCPoint): void {
        // Get the target position for this action
        const targetPosition = this.getTargetPosition();

        switch (action) {
            case CollisionAction.Cancel:
                this.cancel();
                break;

            case CollisionAction.Proceed:
                // User chose to proceed despite collision - remove current action and create new one with collision bypass
                ActionBus.Instance.completeAction(this);
                const proceedAction = new MoveAction(targetPosition.coordinateType, targetPosition.x, targetPosition.y, targetPosition.z, undefined, this.moveType, true);
                ActionBus.Instance.addAction(proceedAction);
                break;

            case CollisionAction.MoveSafe:
                // Move to the safe position instead - remove current action and create new one
                if (safePosition) {
                    ActionBus.Instance.completeAction(this);
                    const safeAction = new MoveAction(safePosition.coordinateType, safePosition.x, safePosition.y, safePosition.z, undefined, this.moveType);
                    ActionBus.Instance.addAction(safeAction);
                } else {
                    this.cancel(); // Fallback if no safe position available
                }
                break;
        }
    }

    /**
     * Execute the move immediately without delay
     */
    public async executeImmediate(targetPosition?: CNCPoint): Promise<void> {
        // Use provided target or calculate it
        const finalTarget = targetPosition || this.getTargetPosition();

        try {
            // Call the machine interface to perform the actual move
            // - Simulator: SimulatorCNCMovement.MoveTo() will update currentMachinePoint directly
            // - Centroid: CentroidCNCMovement.MoveTo() will call the API, position updated via SignalR DRO events
            const machine = Machine.getInstance();
            await machine.movement.MoveTo(finalTarget, MovementCoordinateType.WorkZero);

            Logger.Instance.log(LogCategory.UserInterface, `Move executed successfully to: X=${finalTarget.x.toFixed(3)}, Y=${finalTarget.y.toFixed(3)}, Z=${finalTarget.z.toFixed(3)}`);

        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to execute move:', error);
        } finally {
            // Clear the proposed spindle position since the move is now complete (or failed)
            MachineStateData.Instance.proposedSpindlePosition = null;
            StateManager.propertyChanged(MachineStateData.Instance, 'proposedSpindlePosition');
        }
    }

    /**
     * Get the target position that this action will move to
     */
    getTargetPosition(): CNCPoint {
        // Use extracted utility function to create target position
        return createTargetPosition(this.x, this.y, this.z, this.a);
    }

    /**
     * Create a MoveAction from a CNCPoint
     */
    static fromCNCPoint(point: CNCPoint, moveType: MoveType = MoveType.Coordinates, bypassCollisionDetection: boolean = false, noDelay: boolean = false): MoveAction {
        return new MoveAction(
            point.coordinateType,
            point.x,
            point.y,
            point.z,
            undefined,
            moveType,
            bypassCollisionDetection,
            noDelay
        );
    }

    /**
     * Create a MoveAction that moves only specific axes
     */
    static moveAxis(coordinateType: CoordinateType, axes: { x?: number; y?: number; z?: number; a?: number }, moveType: MoveType = MoveType.Coordinates): MoveAction {
        return new MoveAction(
            coordinateType,
            axes.x,
            axes.y,
            axes.z,
            axes.a,
            moveType
        );
    }


}

// UI Component for MoveAction
interface MoveActionUIProps {
    action: MoveAction;
    delayTime: number;
    startTime: number;
}

function MoveActionUI({ action, delayTime, startTime }: MoveActionUIProps): ReactNode {
    // Don't use useState for timeRemaining - calculate it directly each render
    const [, forceUpdate] = React.useReducer(x => x + 1, 0);
    const [isPaused, setIsPaused] = React.useState(false);
    const [remainingTimeWhenPaused, setRemainingTimeWhenPaused] = React.useState<number | null>(null);

    // Get the current configuration delay for this move type
    const getCurrentConfigDelay = () => {
        const config = ConfigurationData.Instance;
        switch (action.moveType) {
            case MoveType.Simulator:
                return config.simulatorMoveDelay;
            case MoveType.JogPad:
                return config.jogPadMoveDelay;
            case MoveType.Coordinates:
                return config.coordinateMoveDelay;
            case MoveType.MDI:
                return config.mdiToolDelay;
            default:
                return config.coordinateMoveDelay;
        }
    };

    const [adjustedDelayTime, setAdjustedDelayTime] = React.useState(getCurrentConfigDelay());

    // Calculate remaining time based on current props and pause state
    const now = Date.now();
    let elapsed: number;
    let timeRemaining: number;

    if (isPaused && remainingTimeWhenPaused !== null) {
        // Use the saved remaining time when paused
        timeRemaining = remainingTimeWhenPaused;
        elapsed = adjustedDelayTime - timeRemaining;
    } else {
        // Normal time calculation
        elapsed = now - startTime;
        timeRemaining = Math.max(0, adjustedDelayTime - elapsed);
    }

    // Use refs to store stable values that won't trigger effect re-runs
    const delayTimeRef = React.useRef(adjustedDelayTime);
    const startTimeRef = React.useRef(startTime);

    // Update refs when values change
    React.useEffect(() => {
        delayTimeRef.current = adjustedDelayTime;
        startTimeRef.current = startTime;
    }, [adjustedDelayTime, startTime]);

    // Handle move now button
    const handleMoveNow = React.useCallback(() => {
        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        // Execute immediately
        action.executeImmediate();
        ActionBus.Instance.completeAction(action);
    }, [action]);

    React.useEffect(() => {
        const interval = setInterval(() => {
            if (!isPaused) {
                const currentTimeRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));

                // Check if time has expired and execute the action
                if (currentTimeRemaining <= 0) {
                    handleMoveNow();
                } else {
                    forceUpdate(); // Force component to re-render and recalculate timeRemaining
                }
            }
        }, 100); // Update every 100ms for smooth countdown

        return () => {
            clearInterval(interval);
        };
    }, [action.id, isPaused, adjustedDelayTime, startTime, handleMoveNow]); // Reset interval when these change

    // Handle mouse enter/leave for pause functionality
    const handleMouseEnter = () => {
        if (!isPaused) {
            // Clear the existing timeout to actually pause the action
            if (action._timeoutId) {
                clearTimeout(action._timeoutId);
                action._timeoutId = undefined;
            }

            // Calculate and save remaining time when pausing
            const currentRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));
            setRemainingTimeWhenPaused(currentRemaining);
            setIsPaused(true);
        }
    };

    const handleMouseLeave = () => {
        if (isPaused && remainingTimeWhenPaused !== null) {
            // Resume the action with the remaining time
            if (remainingTimeWhenPaused > 0) {
                // Update start time to account for the pause
                action._startTime = Date.now() - (adjustedDelayTime - remainingTimeWhenPaused);

                // Restart the timeout with remaining time
                action._timeoutId = window.setTimeout(() => {
                    handleMoveNow();
                }, remainingTimeWhenPaused);
            }

            setIsPaused(false);
            setRemainingTimeWhenPaused(null);
        }
    };

    // Handle delay adjustment - this updates the configuration for this move type
    const handleDelayChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const newDelaySeconds = parseInt(event.target.value);
        const newDelay = newDelaySeconds * 1000; // Convert seconds to milliseconds

        // Update the configuration setting for this move type
        const config = ConfigurationData.Instance;
        switch (action.moveType) {
            case MoveType.Simulator:
                config.simulatorMoveDelay = newDelay;
                break;
            case MoveType.JogPad:
                config.jogPadMoveDelay = newDelay;
                break;
            case MoveType.Coordinates:
                config.coordinateMoveDelay = newDelay;
                break;
            case MoveType.MDI:
                config.mdiToolDelay = newDelay;
                break;
        }

        // Update the current action's adjusted delay time for UI display
        setAdjustedDelayTime(newDelay);

        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        if (newDelay > 0) {
            if (isPaused) {
                // If paused, just update the remaining time
                setRemainingTimeWhenPaused(newDelay);
            } else {
                // If not paused, restart with new timing
                const currentElapsed = Date.now() - startTime;
                const newTimeRemaining = Math.max(0, newDelay - currentElapsed);

                if (newTimeRemaining > 0) {
                    // Update start time to match new delay
                    action._startTime = Date.now() - (newDelay - newTimeRemaining);

                    action._timeoutId = window.setTimeout(() => {
                        handleMoveNow();
                    }, newTimeRemaining);
                } else {
                    handleMoveNow(); // Execute immediately if no time remaining
                }
            }
        }
    };

    const progressPercent = Math.max(0, (timeRemaining / adjustedDelayTime) * 100);
    const secondsRemaining = Math.ceil(timeRemaining / 1000);
    const delaySeconds = Math.round(adjustedDelayTime / 1000);

    // Get a display name for the move type
    const getMoveTypeName = () => {
        switch (action.moveType) {
            case MoveType.Simulator:
                return 'Simulator';
            case MoveType.JogPad:
                return 'Jog Pad';
            case MoveType.Coordinates:
                return 'Coordinates';
            case MoveType.MDI:
                return 'MDI';
            default:
                return 'Move';
        }
    };

    // Don't show UI if delay is set to 0
    if (adjustedDelayTime <= 0) {
        handleMoveNow(); // Execute immediately
        return null;
    }

    return (
        <ObserveState
            listenTo={ConfigurationData.Instance}
            properties={['darkOverlay', 'modalBackdrop', 'lightTextColor', 'warningColor', 'lightOverlay', 'successColor', 'errorColor']}
            control={() => (
                <div
                    onMouseEnter={handleMouseEnter}
                    onMouseLeave={handleMouseLeave}
                    style={{
                        // Note: position fixed removed - let NotificationArea handle positioning
                        backgroundColor: isPaused
                            ? ConfigurationData.Instance.darkOverlay
                            : ConfigurationData.Instance.modalBackdrop,
                        color: ConfigurationData.Instance.lightTextColor,
                        padding: '12px 16px',
                        borderRadius: '8px',
                        minWidth: '250px',
                        // Note: z-index removed - let NotificationArea handle stacking via ordinal
                        fontFamily: 'Arial, sans-serif',
                        border: isPaused
                            ? `2px solid ${ConfigurationData.Instance.warningColor}`
                            : 'none'
                    }}
                >
                    <div style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '8px' }}>
                        {`Move Command Executing...${isPaused ? ' (PAUSED)' : ''}`}
                    </div>

                    <div style={{ fontSize: '12px', marginBottom: '8px' }}>
                        {`${secondsRemaining} seconds remaining`}
                    </div>

                    <div
                        style={{
                            width: '100%',
                            height: '4px',
                            backgroundColor: ConfigurationData.Instance.lightOverlay,
                            borderRadius: '2px',
                            marginBottom: '8px',
                            overflow: 'hidden'
                        }}
                    >
                        <div
                            style={{
                                width: `${progressPercent}%`,
                                height: '100%',
                                backgroundColor: isPaused
                                    ? ConfigurationData.Instance.warningColor
                                    : ConfigurationData.Instance.successColor,
                                transition: isPaused ? 'none' : 'width 0.1s ease'
                            }}
                        />
                    </div>

                    <div style={{ marginBottom: '8px' }}>
                        <label style={{ fontSize: '11px', display: 'block', marginBottom: '4px' }}>
                            {`${getMoveTypeName()} Delay: ${delaySeconds}s`}
                        </label>
                        <input
                            type="range"
                            min="0"
                            max="20"
                            value={delaySeconds.toString()}
                            onChange={handleDelayChange}
                            style={{
                                width: '100%',
                                height: '4px',
                                background: ConfigurationData.Instance.lightOverlay,
                                outline: 'none',
                                borderRadius: '2px'
                            }}
                        />
                    </div>

                    <div style={{ display: 'flex', gap: '8px' }}>
                        <button
                            onClick={handleMoveNow}
                            style={{
                                backgroundColor: ConfigurationData.Instance.successColor,
                                color: ConfigurationData.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Move Now
                        </button>

                        <button
                            onClick={() => action.cancel()}
                            style={{
                                backgroundColor: ConfigurationData.Instance.errorColor,
                                color: ConfigurationData.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}
        />
    );
}
