import React, { useState } from 'react';
import {
  Box,
  Button,
  Typography,
  Slider,
} from '@mui/material';
import { MachineStateData } from '../../data/MachineStateData';
import { CNCPoint } from '../../data/CNCPoint';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { ActionBus } from '../../utils/actions/ActionBus';

export function ZJogControls() {
  const [jogAmount, setJogAmount] = useState(0.1);

  const handleJog = (deltaZ: number) => {
    const machineState = MachineStateData.Instance;
    
    // Use proposed spindle position if it exists, otherwise use current machine position
    const basePosition = machineState.proposedSpindlePosition || machineState.currentMachinePoint;
    
    // Create new position with same coordinate type as base position
    const newPosition = new CNCPoint(
      basePosition.x,
      basePosition.y,
      basePosition.z + deltaZ,
      basePosition.coordinateType  // Preserve the coordinate type from base position
    );
    
    // Create the move action with bypassCollisionDetection=true and noDelay=true for instant jog movement
    const moveAction = MoveAction.fromCNCPoint(newPosition, MoveType.JogPad, true, true);
    ActionBus.Instance.addAction(moveAction);
  };

  const handleJogUp = () => {
    handleJog(jogAmount);
  };

  const handleJogDown = () => {
    handleJog(-jogAmount);
  };

  const handleJogByAmount = (amount: number) => {
    handleJog(amount);
  };

  const handleJogAmountChange = (amount: number) => {
    setJogAmount(amount);
  };
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 3 }}>
      <Typography variant="body2" sx={{ mb: 2 }}>
        Z-Axis Jog Controls
      </Typography>
      
      {/* Main Jog Buttons with Preset Amount Buttons */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
        {/* Preset Jog Amount Buttons - Left Side */}
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(1)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            1
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(0.1)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            .1
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(0.01)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            .01
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(0.001)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            .001
          </Button>
        </Box>
        
        {/* +/- Buttons */}
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <Button 
            variant="contained" 
            color="primary"
            sx={{ minWidth: 80, minHeight: 50, fontSize: '1.5rem', mb: 1 }}
            onClick={handleJogUp}
          >
            +
          </Button>
          <Button 
            variant="contained" 
            color="primary"
            sx={{ minWidth: 80, minHeight: 50, fontSize: '1.5rem' }}
            onClick={handleJogDown}
          >
            -
          </Button>
        </Box>
        
        {/* Preset Jog Amount Buttons - Right Side (Negative) */}
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(-1)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            -1
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(-0.1)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            -.1
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(-0.01)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            -.01
          </Button>
          <Button
            variant="outlined"
            size="small"
            onClick={() => handleJogByAmount(-0.001)}
            sx={{ minWidth: 45, fontSize: '0.75rem' }}
          >
            -.001
          </Button>
        </Box>
      </Box>
      
      {/* Jog Amount Slider for Fine Control */}
      <Box sx={{ width: '100%', maxWidth: 300, display: 'flex', alignItems: 'center', gap: 2 }}>
        <Slider
          value={jogAmount}
          min={0.001}
          max={1}
          step={0.001}
          onChange={(_, value) => handleJogAmountChange(value as number)}
          valueLabelDisplay="auto"
          valueLabelFormat={(value) => value.toFixed(3)}
          sx={{ flex: 1 }}
        />
        <Typography variant="body2" sx={{ minWidth: '60px', textAlign: 'right' }}>
          {jogAmount.toFixed(3)}"
        </Typography>
      </Box>
    </Box>
  );
};
