import { PlayArrow as PlayArrowIcon } from '@mui/icons-material';
import React from 'react';
import { CNCPoint } from "../../data/CNCPoint";
import { ToolLibrary } from "../../data/Common/ToolLibrary";
import { MachineData } from "../../data/MachineData";
import { MachineStateData } from "../../data/MachineStateData";
import { FlowStep } from "../FlowStep";
import { FlowStepData } from "../FlowStepData";

export class StartStep extends FlowStep {
    readonly __type = 'StartStep';
    readonly category = ['System'];
    readonly name = 'Start';
    readonly description = 'Entry point for flow execution';
    readonly canAdd = false; // Start step cannot be added via dialog

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(PlayArrowIcon, { sx: { color: 'success.main' } });
    }

    // Static path constants
    static readonly OUTPUT_PATH = 'output';

    constructor(id: string = 'start') {
        super(id);
    }

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        // Add initial data based on flow context
        await this.addInitialData(data);

        // Start step always proceeds to its output path
        return StartStep.OUTPUT_PATH;
    }

    /**
     * Add initial data to the flow based on flow type
     * For General flows: current point, current tool information
     * For ToolChange flows: includes target tool information as well
     */
    private async addInitialData(data: FlowStepData): Promise<void> {
        const machineState = MachineStateData.Instance;
        const machineData = MachineData.Instance;
        const toolLibrary = ToolLibrary.Instance;

        // Add current machine position
        const currentPoint = new CNCPoint(
            machineState.currentMachinePoint.x,
            machineState.currentMachinePoint.y,
            machineState.currentMachinePoint.z,
            machineState.currentMachinePoint.coordinateType
        );
        data.elements.push(currentPoint);

        // Create current tool information object
        const currentTool = toolLibrary.getToolByNumber(machineState.currentToolNumber);
        if (currentTool) {
            const currentToolInfo = {
                tool: currentTool,
                toolNumber: currentTool.toolNumber,
                toolName: currentTool.displayName,
                diameter: currentTool.cuttingDiameter,
                length: currentTool.lengthBelowHolder,
                type: currentTool.cutterType,
                measured: currentTool.toolMeasured,
                measuredLength: currentTool.measuredLength,
                offsetX: currentTool.toolOffsetX,
                offsetY: currentTool.toolOffsetY,
                toolLoaded: currentTool.toolNumber > 0, // Tool is loaded if number > 0
                inATC: false,
                holderLocation: null as any
            };

            data.elements.push(currentTool);

            // Add ATC information if the machine has ATC
            if (machineData.hasATC) {
                // Check if current tool's number matches a holder
                const toolClamp = machineData.atcToolClamps.find(clamp => clamp.clampNumber === currentTool.toolNumber);
                if (toolClamp) {
                    currentToolInfo.holderLocation = {
                        clampNumber: toolClamp.clampNumber,
                        offsetX: toolClamp.offsetX,
                        offsetY: toolClamp.offsetY,
                        offsetZ: toolClamp.offsetZ,
                        absoluteX: machineData.atcLocation.x + toolClamp.offsetX,
                        absoluteY: machineData.atcLocation.y + toolClamp.offsetY,
                        absoluteZ: machineData.atcLocation.z + toolClamp.offsetZ
                    };
                    currentToolInfo.inATC = true;
                }
            }

            data.setVariable('current', {
                point: currentPoint,
                tool: currentToolInfo,
                feedRate: machineState.currentFeedRate,
                spindleSpeed: machineState.currentSpindleSpeed,
                fastTravelRate: machineState.currentFastTravelRate,
                fixtureNumber: machineState.currentFixtureNumber
            });
        }

        // Add machine state information
        data.setVariable('machine', {
            isHomed: machineState.isHomed,
            hasATC: machineData.hasATC,
            atc: machineData.hasATC ? {
                numberOfTools: machineData.atcNumberOfTools,
                location: {
                    x: machineData.atcLocation.x,
                    y: machineData.atcLocation.y,
                    z: machineData.atcLocation.z
                }
            } : null
        });

        // Check for Tool Change flow by looking for ToTool parameter
        // ToTool is set by CallFlowStep or FlowEngine when executing a ToolChange type flow
        const toToolNumber = data.getVariable('ToTool');

        // For tool change flows, add target tool information
        if (toToolNumber !== undefined && typeof toToolNumber === 'number') {
            const targetTool = toolLibrary.getToolByNumber(toToolNumber);
            if (targetTool) {
                const targetToolInfo = {
                    tool: targetTool,
                    toolNumber: targetTool.toolNumber,
                    toolName: targetTool.displayName,
                    diameter: targetTool.cuttingDiameter,
                    length: targetTool.lengthBelowHolder,
                    type: targetTool.cutterType,
                    measured: targetTool.toolMeasured,
                    measuredLength: targetTool.measuredLength,
                    offsetX: targetTool.toolOffsetX,
                    offsetY: targetTool.toolOffsetY,
                    toolLoaded: false, // Target tool not yet loaded
                    inATC: false,
                    holderLocation: null as any
                };

                data.elements.push(targetTool);

                // Add target tool ATC information if applicable
                if (machineData.hasATC) {
                    // Check if target tool number matches a holder
                    const targetToolClamp = machineData.atcToolClamps.find(clamp => clamp.clampNumber === targetTool.toolNumber);
                    if (targetToolClamp) {
                        targetToolInfo.holderLocation = {
                            clampNumber: targetToolClamp.clampNumber,
                            offsetX: targetToolClamp.offsetX,
                            offsetY: targetToolClamp.offsetY,
                            offsetZ: targetToolClamp.offsetZ,
                            absoluteX: machineData.atcLocation.x + targetToolClamp.offsetX,
                            absoluteY: machineData.atcLocation.y + targetToolClamp.offsetY,
                            absoluteZ: machineData.atcLocation.z + targetToolClamp.offsetZ
                        };
                        targetToolInfo.inATC = true;
                    }
                }

                data.setVariable('target', {
                    tool: targetToolInfo
                });
            }
        }
    }

    results(): string[] {
        return [StartStep.OUTPUT_PATH]; // Start step has one output path
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return null; // No UI for now
    }
}
