import { CompareArrows as CompareArrowsIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    ButtonGroup,
    Card,
    CardContent,
    FormControl,
    InputLabel,
    MenuItem,
    Select,
    TextField,
    Typography
} from '@mui/material';
import React from 'react';
import { FlowDataSelector } from '../../components/Common/FlowDataSelector';
import { NumberInput } from '../../components/Common/NumberInput';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { FlowStep } from "../FlowStep";
import { FlowStepData } from "../FlowStepData";
import { ComparisonType, EqualsStepData } from './EqualsStepData';

export class EqualsStep extends FlowStep {
    readonly __type = 'EqualsStep';
    readonly category = ['Logic'];
    readonly name = 'Equals';
    readonly description = 'Compares two values for equality';

    // StateManager-based step data
    public stepData: EqualsStepData = new EqualsStepData();

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(CompareArrowsIcon, { sx: { color: 'primary.main' } });
    }

    // Static path constants
    static readonly YES_PATH = 'yes';
    static readonly NO_PATH = 'no';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            // Simulate comparison result for testing
            return Math.random() > 0.5 ? EqualsStep.YES_PATH : EqualsStep.NO_PATH;
        }

        try {
            // Get left value from data
            const leftValue = this.getValueFromData(data, this.stepData.leftDataPath);
            if (leftValue === undefined) {
                console.error('Left data path not found:', this.stepData.leftDataPath);
                return EqualsStep.NO_PATH;
            }

            // Get right value (either from data or direct value)
            let rightValue: any;
            if (this.stepData.comparisonType === ComparisonType.DataElement) {
                rightValue = this.getValueFromData(data, this.stepData.rightDataPath);
                if (rightValue === undefined) {
                    console.error('Right data path not found:', this.stepData.rightDataPath);
                    return EqualsStep.NO_PATH;
                }
            } else {
                rightValue = this.stepData.getCurrentValue();
            }

            // Perform comparison
            const isEqual = this.compareValues(leftValue, rightValue);
            return isEqual ? EqualsStep.YES_PATH : EqualsStep.NO_PATH;

        } catch (error) {
            console.error('Equals step execution failed:', error);
            return EqualsStep.NO_PATH;
        }
    }

    private getValueFromData(data: FlowStepData, path: string): any {
        if (!path) return undefined;

        const allData = data.getAllData();
        const pathParts = path.split('.');

        let current = allData;
        for (const part of pathParts) {
            if (current && typeof current === 'object' && part in current) {
                current = current[part];
            } else {
                return undefined;
            }
        }

        return current;
    }

    private compareValues(left: any, right: any): boolean {
        // Type-aware comparison
        if (typeof left !== typeof right) {
            // Try to convert to same type if possible
            if (this.stepData.dataType === 'number') {
                const leftNum = Number(left);
                const rightNum = Number(right);
                if (!isNaN(leftNum) && !isNaN(rightNum)) {
                    return leftNum === rightNum;
                }
            } else if (this.stepData.dataType === 'string') {
                return String(left) === String(right);
            } else if (this.stepData.dataType === 'boolean') {
                return Boolean(left) === Boolean(right);
            }
        }

        // Direct comparison
        return left === right;
    }

    results(): string[] {
        return [EqualsStep.YES_PATH, EqualsStep.NO_PATH];
    }

    renderStepUI(): React.ReactNode {
        return super.renderStepUI(); // Use default step UI (icon + name)
    }

    private renderValueEditor(): React.ReactNode {
        switch (this.stepData.dataType) {
            case 'string':
                return (
                    <TextField
                        fullWidth
                        label="String Value"
                        value={this.stepData.stringValue}
                        onChange={(e) => {
                            this.stepData.stringValue = e.target.value;
                        }}
                        margin="normal"
                    />
                );

            case 'number':
                return (
                    <NumberInput
                        label="Number Value"
                        value={this.stepData.numberValue}
                        onChange={(value) => {
                            this.stepData.numberValue = value;
                        }}
                        fullWidth
                        margin="normal"
                    />
                );

            case 'boolean':
                return (
                    <Box sx={{ mt: 2 }}>
                        <Typography variant="body2" sx={{ mb: 1 }}>
                            Compare to Value
                        </Typography>
                        <ButtonGroup variant="outlined" fullWidth>
                            <Button
                                variant={this.stepData.booleanValue ? "contained" : "outlined"}
                                onClick={() => {
                                    this.stepData.booleanValue = true;
                                }}
                            >
                                Is True
                            </Button>
                            <Button
                                variant={!this.stepData.booleanValue ? "contained" : "outlined"}
                                onClick={() => {
                                    this.stepData.booleanValue = false;
                                }}
                            >
                                Is False
                            </Button>
                        </ButtonGroup>
                    </Box>
                );

            default:
                return null;
        }
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const leftValue = this.getValueFromData(data, this.stepData.leftDataPath);
        const rightValue = this.stepData.comparisonType === ComparisonType.DataElement
            ? this.getValueFromData(data, this.stepData.rightDataPath)
            : this.stepData.getCurrentValue();

        return (
            <Typography variant="caption">
                {String(leftValue)} equals {String(rightValue)}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void, flow: any, flowStep?: any }): React.ReactNode {
        // Extract flow from props - we'll use 'this' as the flowStep
        const { flow } = props;

        return (
            <ObserveState
                key="equals-step-edit-ui"
                listenTo={this.stepData}
                properties={['dataType', 'leftDataPath', 'comparisonType', 'rightDataPath', 'stringValue', 'numberValue', 'booleanValue']}
                control={() => (
                    <Box sx={{ minWidth: 500 }}>
                        <Box sx={{ p: 2, minWidth: 400 }}>
                            <Typography variant="h6" gutterBottom>
                                Equals Comparison Configuration
                            </Typography>

                            {/* Data Type Selection */}
                            <FormControl fullWidth margin="normal">
                                <InputLabel>Data Type</InputLabel>
                                <Select
                                    value={this.stepData.dataType}
                                    label="Data Type"
                                    onChange={(e) => {
                                        this.stepData.dataType = e.target.value;
                                    }}
                                >
                                    <MenuItem value="string">String</MenuItem>
                                    <MenuItem value="number">Number</MenuItem>
                                    <MenuItem value="boolean">Boolean</MenuItem>
                                </Select>
                            </FormControl>

                            {/* Left Data Element Selector */}
                            <Card variant="outlined" sx={{ mt: 3 }}>
                                <CardContent>
                                    <FlowDataSelector
                                        flow={flow}
                                        flowStep={this}
                                        allowedTypes={[this.stepData.dataType]}
                                        currentSelection={this.stepData.leftDataPath ? [this.stepData.leftDataPath] : []}
                                        onChange={(paths) => {
                                            this.stepData.leftDataPath = paths.length > 0 ? paths[0] : '';
                                        }}
                                        label="Left Value (Data Element)"
                                    />
                                </CardContent>
                            </Card>

                            {/* Visual Separator */}
                            <Box sx={{
                                mt: 2,
                                mb: 2,
                                textAlign: 'center',
                                py: 2,
                                borderTop: '3px solid',
                                borderBottom: '3px solid',
                                borderColor: 'primary.main',
                                backgroundColor: 'grey.50'
                            }}>
                                <Typography variant="h5" sx={{
                                    fontWeight: 'bold',
                                    letterSpacing: 2,
                                    color: 'primary.main'
                                }}>
                                    EQUALS
                                </Typography>
                            </Box>

                            {/* Second Element Section */}
                            <Card variant="outlined" sx={{ mt: 2 }}>
                                <CardContent>
                                    {/* Comparison Type Selection */}
                                    <ButtonGroup fullWidth variant="outlined" sx={{ mb: 2 }}>
                                        <Button
                                            variant={this.stepData.comparisonType === ComparisonType.Value ? 'contained' : 'outlined'}
                                            onClick={() => {
                                                this.stepData.comparisonType = ComparisonType.Value;
                                            }}
                                        >
                                            Value
                                        </Button>
                                        <Button
                                            variant={this.stepData.comparisonType === ComparisonType.DataElement ? 'contained' : 'outlined'}
                                            onClick={() => {
                                                this.stepData.comparisonType = ComparisonType.DataElement;
                                            }}
                                        >
                                            Data Element
                                        </Button>
                                    </ButtonGroup>

                                    {/* Right Side - Data Element or Value */}
                                    {this.stepData.comparisonType === ComparisonType.DataElement ? (
                                        <FlowDataSelector
                                            flow={flow}
                                            flowStep={this}
                                            allowedTypes={[this.stepData.dataType]}
                                            currentSelection={this.stepData.rightDataPath ? [this.stepData.rightDataPath] : []}
                                            onChange={(paths) => {
                                                this.stepData.rightDataPath = paths.length > 0 ? paths[0] : '';
                                            }}
                                            label="Right Value (Data Element)"
                                        />
                                    ) : (
                                        this.renderValueEditor()
                                    )}
                                </CardContent>
                            </Card>
                        </Box>
                    </Box>
                )}
            />
        );
    }

    // Serialization
    public toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['stepData']);
        return {
            ...baseData,
            __type: this.__type,
            stepData: this.stepData.toJSON()
        };
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['stepData']);
        if (data.stepData) {
            this.stepData.fromJSON(data.stepData);
        }
    }
}
