import { IStorable } from '../common/IStorable';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { SaveableDataBase } from './Common/SaveableDataBase';
import { UnitOfMeasure } from './Common/UnitOfMeasure';



// Ensuring correct import path for StateManager
/**
 * Z-axis zero location enum
 * Direct conversion from C# ZZeroLocation enum
 */
export enum ZZeroLocation {
  Top = 'Top',
  Bed = 'Bed'
}

/**
 * X-axis direction enum
 * Direct conversion from C# XDirection enum
 */
export enum XDirection {
  Across = 'Across',
  Side = 'Side'
}

/**
 * Rotary axis configuration enum
 * None: No rotary axis
 * Fixed: Rotary axis is permanently mounted to the base
 * Movable: Rotary axis can be placed on the bed/fixture mounting point
 */
export enum RotaryAxis {
  None = 'None',
  Fixed = 'Fixed',
  Movable = 'Movable'
}

/**
 * Rotary axis direction enum
 */
export enum RotaryAxisDirection {
  X = 'X',
  Y = 'Y'
}

/**
 * Step frequency configuration enum
 * Supported step frequencies for different hardware configurations
 */
export enum StepFrequency {
  Freq100k = 100000,   // 100,000 steps/second
  Freq200k = 200000,   // 200,000 steps/second
  Freq240k = 240000,   // 240,000 steps/second
  Freq300k = 300000,   // 300,000 steps/second
  Freq400k = 400000    // 400,000 steps/second
}

/**
 * Get user-friendly label for step frequency
 * @param frequency - The step frequency enum value
 * @returns Formatted string with commas and units
 */
export function getStepFrequencyLabel(frequency: StepFrequency): string {
  return `${frequency.toLocaleString()} steps/second`;
}

/**
 * Drill bit offset interface
 * Represents the X,Y offset of each drill bit from the drill head corner
 */
export interface DrillBitOffset {
  x: number;
  y: number;
}

export enum AxisType {
  X = 'X',
  Y = 'Y',
  Z = 'Z',
  A = 'A (rotary)',
  Unset = 'Unset',
  XSlave = 'X Slave',
  YSlave = 'Y Slave',
}

