  private constructor() {
    super();

    // All initialization is done inline above
    // Initialize ATC tool clamps with default positions
    this.initializeATCToolClamps();

    // Initialize axis configurations
    this.initializeAxisConfigurations();

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Initialize ATC tool clamps based on number of tools
   * Creates a default linear arrangement along X axis
   */
  private initializeATCToolClamps(): void {
    this._atcToolClamps = [];
    for (let i = 0; i < this._atcNumberOfTools; i++) {
      // Default linear arrangement: 2" spacing along X axis
      const toolClamp = new ATCToolClamp(
        i + 1, // Tool clamp number (1-based)
        i * 2, // X offset: 0, 2, 4, 6, etc.
        0,     // Y offset: all at same Y position
        0      // Z offset: all at same Z position
      );
      this._atcToolClamps.push(toolClamp);
    }
  }





  /**
   * Initialize axis configurations
   * Creates a fixed array of 6 axes in order: X, Y, Z, X2, A, Unused
   */
  private initializeAxisConfigurations(): void {
    const axisTypes = [AxisType.X, AxisType.Y, AxisType.Z, AxisType.A, AxisType.XSlave, AxisType.Unset];

    this._axisConfigurations = axisTypes.map((axisType, index) => {
      return new AxisConfig(axisType, index + 1);
    });
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): MachineData {
    if (!MachineData._instance) {
      MachineData._instance = new MachineData();
      // Setup auto-save after instance is fully created
      MachineData._instance.setupAutoSave();
    }
    return MachineData._instance;
  }



