  /**
   * IStorable implementation - serialize to JSON
   */
  public toJSON(): object {
    const baseData = DataUtilities.getStorageData(this, [
      '_instance',
      '_atcLocation', '_atcStructure', '_atcToolHolders', '_axisConfigurations',
      '_spindleConfig', '_secondSpindleConfig'
    ]); // Exclude sub-objects that need special handling    // Handle sub-objects explicitly with proper serialization
    return {
      ...baseData,
      _stepFrequency: this._stepFrequency, // Explicitly include to ensure serialization
      _driveFaultDelay: this._driveFaultDelay, // Explicitly include to ensure serialization
      _atcLocation: this._atcLocation.toJSON(),
      _atcStructure: this._atcStructure.toJSON(),
      _atcToolClamps: this._atcToolClamps.map(clamp => clamp.toJSON()),
      _axisConfigurations: this._axisConfigurations.map(axis => axis.toJSON())
    };
  }

  /**
   * IStorable implementation - deserialize from JSON
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load basic properties automatically
    DataUtilities.loadStorageData(this, data, [
      '_instance',
      '_atcLocation', '_atcStructure', '_atcToolHolders', '_axisConfigurations'
    ]); // Exclude sub-objects that need special handling

    // Handle ATC IStorable sub-objects
    if (data._atcLocation) {
      this._atcLocation.fromJSON(data._atcLocation);
    }

    if (data._atcStructure) {
      this._atcStructure.fromJSON(data._atcStructure);
    }

    // Handle ATC tool clamps array
    if (data._atcToolClamps && Array.isArray(data._atcToolClamps)) {
      this._atcToolClamps = data._atcToolClamps.map((clampData: any) => {
        const clamp = new ATCToolClamp(1); // Temporary clamp number
        clamp.fromJSON(clampData);
        return clamp;
      });
    } else {
      // If no ATC data, initialize with defaults
      this.initializeATCToolClamps();
    }

    // Handle axis configurations array
    if (data._axisConfigurations && Array.isArray(data._axisConfigurations)) {
      // Ensure we always have exactly 6 axis configurations
      if (data._axisConfigurations.length === 6) {
        this._axisConfigurations = data._axisConfigurations.map((axisData: any, index: number) => {
          const axis = new AxisConfig(AxisType.X, index + 1); // Temporary values
          axis.fromJSON(axisData);
          return axis;
        });
      } else {
        // If wrong number of axes, reinitialize with defaults
        this.initializeAxisConfigurations();
      }
    } else {
      // If no axis data, initialize with defaults
      this.initializeAxisConfigurations();
    }
  }
