import React from "react";
import { Box, Typography } from '@mui/material';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { ZAxisReferenceType } from '../common/types';
import { ConfigurationData } from "../../../../data/ConfigurationData";

export class PositionTouchplateStep extends BaseWizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "Start Touch Off", "Back");
  }

  getTitle(): string {
    return "Position Touch Plate";
  }

  nextStep(): WizardStep | null {
    const { TouchplateProgressStep } = require('./TouchplateProgressStep');
    return new TouchplateProgressStep(this.wizard, this);
  }

  handleNext(): void {
    // Start the touchplate process
    this.wizard.state.isProcessing = true;
    super.handleNext();
  }

  private getReferenceTitle(): string {
    switch (this.wizard.state.referenceType) {
      case ZAxisReferenceType.BED:
        return 'Machine Bed';
      case ZAxisReferenceType.SPOILBOARD:
        return 'Spoilboard';
      case ZAxisReferenceType.MATERIAL:
        return 'Material Surface';
      default:
        return 'Surface';
    }
  }

  render(): React.ReactNode {
    return (
      <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        <div style={{ flex: 1 }}>
          <Box sx={{ display: 'flex', height: '100%' }}>
            <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
              <Typography variant="h6" sx={{ mb: 2 }}>
                Position Touch Plate
              </Typography>
              <Typography variant="body1" sx={{ mb: 3 }}>
                Position the touch plate under the tool on the {this.getReferenceTitle().toLowerCase()} and press Start Touch-off.
              </Typography>
            </Box>
            <Box sx={{ 
              width: '50%', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center', 
              backgroundColor: ConfigurationData.Instance.lightBackgroundColor, 
              borderRadius: 1 
            }}>
              <Typography variant="body2" color="text.secondary">
                [Picture: Touch plate positioned under tool]
              </Typography>
            </Box>
          </Box>
        </div>
        {this.renderButtons()}
      </div>
    );
  }
}
