console.log('=== INDEX STARTING ===');

const React = require('react');
const ReactDOM = require('react-dom/client');

console.log('=== REACT LOADED ===', React.version);

// Import the App component and ErrorBoundary
const App = require('./App').default;
const ErrorBoundary = require('./ErrorBoundary').default;

const container = document.getElementById('root');
// console.log('=== ROOT FOUND ===', container);

if (container) {
    const root = ReactDOM.createRoot(container);
    
    // console.log('=== RENDERING APP WITH ERROR BOUNDARY ===');
    root.render(
        React.createElement(ErrorBoundary, null,
            React.createElement(App)
        )
    );
    // console.log('=== RENDER COMPLETE ===');
} 
