import React from 'react';
import { EdgeProps, getBezierPath } from 'reactflow';
import { Box, IconButton } from '@mui/material';
import { Add } from '@mui/icons-material';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface FlowStepEdgeData {
  onEdgeClick?: (event: React.MouseEvent, edgeId: string) => void;
}

export const FlowStepEdge: React.FC<EdgeProps<FlowStepEdgeData>> = ({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  sourcePosition,
  targetPosition,
  style = {},
  data,
  markerEnd,
}) => {
  
  const [edgePath, labelX, labelY] = getBezierPath({
    sourceX,
    sourceY,
    sourcePosition,
    targetX,
    targetY,
    targetPosition,
  });

  const handleEdgeClick = (event: React.MouseEvent) => {
    event.stopPropagation();
    if (data?.onEdgeClick) {
      data.onEdgeClick(event, id);
    }
  };

  const handleMouseEnter = () => {
    ConfigurationState.Instance.hoveredEdgeId = id;
  };

  const handleMouseLeave = () => {
    ConfigurationState.Instance.hoveredEdgeId = null;
  };

  return (
    <ObserveState
      listenTo={ConfigurationState.Instance}
      properties={['hoveredEdgeId']}
      control={() => {
        const isHovered = ConfigurationState.Instance.hoveredEdgeId === id;
        
        return (
          <>
            {/* Main edge path */}
            <path
              id={id}
              style={style}
              className="react-flow__edge-path"
              d={edgePath}
              markerEnd={markerEnd}
              onMouseEnter={handleMouseEnter}
              onMouseLeave={handleMouseLeave}
              onClick={handleEdgeClick}
            />
            
            {/* Invisible wider path for easier hovering */}
            <path
              d={edgePath}
              fill="none"
              strokeOpacity={0}
              strokeWidth={20}
              className="react-flow__edge-interaction"
              onMouseEnter={handleMouseEnter}
              onMouseLeave={handleMouseLeave}
              onClick={handleEdgeClick}
            />
            
            {/* Add button that appears on hover */}
            {isHovered && (
              <foreignObject
                width={24}
                height={24}
                x={labelX - 12}
                y={labelY - 12}
                className="edgebutton-foreignobject"
                requiredExtensions="http://www.w3.org/1999/xhtml"
              >
                <Box
                  sx={{
                    width: 24,
                    height: 24,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    pointerEvents: 'all'
                  }}
                  onMouseEnter={handleMouseEnter}
                  onMouseLeave={handleMouseLeave}
                >
                  <IconButton
                    size="small"
                    onClick={handleEdgeClick}
                    sx={{
                      width: 20,
                      height: 20,
                      backgroundColor: 'white',
                      color: 'black',
                      border: `1px solid #888888`,
                      '&:hover': {
                        backgroundColor: '#f5f5f5',
                        borderColor: '#666666',
                        transform: 'scale(1.1)',
                      },
                      transition: 'all 0.2s ease-in-out',
                      boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
                    }}
                    title="Insert step here"
                  >
                    <Add sx={{ fontSize: '0.7rem' }} />
                  </IconButton>
                </Box>
              </foreignObject>
            )}
          </>
        );
      }}
    />
  );
};
