import { CNCPoint } from '../../../../data/CNCPoint';
import { MachineStateData } from '../../../../data/MachineStateData';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { ViewStyle } from '../../../../data/Common/ViewStyle';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { SimulatorView } from '../../../../data/Common/SimulatorView';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ZAxisReferenceType } from './types';

/**
 * Creates a simulator view configuration optimized for calibration workflows
 */
export function createCalibrationSimulatorView(): SimulatorView {
  const view = new SimulatorView();
  // Copy settings from default view
  const defaultView = ConfigurationData.Instance.defaultView;
  view.workHome = defaultView.workHome;
  view.toolpaths = defaultView.toolpaths;
  view.softLimits = defaultView.softLimits;
  view.material = defaultView.material;
  view.gantry = ViewStyle.Hide; // Hide gantry for cleaner view
  view.base = ViewStyle.Hide;   // Hide base for cleaner view  
  view.bed = defaultView.bed;
  view.railing = defaultView.railing;
  view.spindle = defaultView.spindle;
  view.workPiece = defaultView.workPiece;
  view.spoilBoard = defaultView.spoilBoard;
  view.clamps = ViewStyle.Hide; // Hide clamps for cleaner calibration view
  view.tool = defaultView.tool;
  view.rotary = defaultView.rotary;
  return view;
}

/**
 * Jogs the machine by the specified amounts in machine coordinates
 */
export function jogMachineXYZ(deltaX: number, deltaY: number, deltaZ: number) {
  const machineState = MachineStateData.Instance;
  
  // Get current position
  const currentPosition = machineState.currentMachinePoint;
  
  // Calculate new position
  const newPosition = new CNCPoint(
    currentPosition.x + deltaX,
    currentPosition.y + deltaY,
    currentPosition.z + deltaZ,
    CoordinateType.MachineZero
  );
  
  // Update machine position
  machineState.currentMachinePoint = newPosition;
  StateManager.propertyChanged(machineState, 'currentMachinePoint');
}

/**
 * Gets the title for a reference type
 */
export function getReferenceTitle(referenceType: ZAxisReferenceType): string {
  switch (referenceType) {
    case ZAxisReferenceType.BED:
      return 'Machine Bed';
    case ZAxisReferenceType.SPOILBOARD:
      return 'Spoilboard';
    case ZAxisReferenceType.MATERIAL:
      return 'Material Surface';
    default:
      return 'Surface';
  }
}
