import {
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    FormControlLabel,
    InputLabel,
    MenuItem,
    Select,
    TextField,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { FlowType } from '../../flow/Flow';

interface FlowCreateDialogProps {
    open: boolean;
    onClose: () => void;
    onCreateFlow: (name: string, flowType: FlowType, categoryName?: string, canBeCalledAsStep?: boolean) => void;
}

export function FlowCreateDialog({ open, onClose, onCreateFlow }: FlowCreateDialogProps) {
    const [flowName, setFlowName] = useState('');
    const [flowType, setFlowType] = useState<FlowType>(FlowType.General);
    const [categoryName, setCategoryName] = useState('');
    const [exposeAsAction, setExposeAsAction] = useState(false);
    const [canBeCalledAsStep, setCanBeCalledAsStep] = useState(false);
    const [nameError, setNameError] = useState('');

    const handleClose = () => {
        // Reset form
        setFlowName('');
        setFlowType(FlowType.General);
        setCategoryName('');
        setExposeAsAction(false);
        setCanBeCalledAsStep(false);
        setNameError('');
        onClose();
    };

    const validateName = (name: string): boolean => {
        if (!name.trim()) {
            setNameError('Flow name is required');
            return false;
        }
        if (name.length > 50) {
            setNameError('Flow name must be 50 characters or less');
            return false;
        }
        if (!/^[a-zA-Z0-9\s\-_]+$/.test(name)) {
            setNameError('Flow name can only contain letters, numbers, spaces, hyphens, and underscores');
            return false;
        }
        setNameError('');
        return true;
    };

    const handleCreate = () => {
        if (!validateName(flowName)) {
            return;
        }

        onCreateFlow(
            flowName.trim(),
            flowType,
            exposeAsAction && categoryName.trim() ? categoryName.trim() : undefined,
            canBeCalledAsStep
        );
        handleClose();
    };

    const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const value = event.target.value;
        setFlowName(value);
        if (nameError) {
            validateName(value);
        }
    };

    return (
        <Dialog
            open={open}
            onClose={handleClose}
            maxWidth="sm"
            fullWidth
            PaperProps={{
                sx: {
                    borderRadius: 2,
                }
            }}
        >
            <DialogTitle sx={{
                backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                borderBottom: `1px solid ${ConfigurationDataColors.Instance.borderColor}`
            }}>
                Create New Flow
            </DialogTitle>

            <DialogContent sx={{ pt: 3 }}>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <TextField
                        autoFocus
                        label="Flow Name"
                        fullWidth
                        value={flowName}
                        onChange={handleNameChange}
                        error={!!nameError}
                        helperText={nameError || 'Enter a descriptive name for your flow'}
                        placeholder="e.g., Material Setup, Tool Change Sequence"
                    />

                    <FormControl fullWidth>
                        <InputLabel>Flow Type</InputLabel>
                        <Select
                            value={flowType}
                            label="Flow Type"
                            onChange={(e) => setFlowType(e.target.value as FlowType)}
                        >
                            {Object.values(FlowType).map((type) => (
                                <MenuItem key={type} value={type}>
                                    {type}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>

                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={exposeAsAction}
                                onChange={(e) => setExposeAsAction(e.target.checked)}
                                sx={{
                                    color: ConfigurationDataColors.Instance.primaryColor,
                                    '&.Mui-checked': {
                                        color: ConfigurationDataColors.Instance.primaryColor,
                                    },
                                }}
                            />
                        }
                        label={
                            <Box>
                                <Typography variant="body2">
                                    Expose as Action
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Make this flow available as a quick action button
                                </Typography>
                            </Box>
                        }
                    />

                    {exposeAsAction && (
                        <TextField
                            label="Action Category"
                            fullWidth
                            value={categoryName}
                            onChange={(e) => setCategoryName(e.target.value)}
                            helperText="Optional: Group this action under a category"
                            placeholder="e.g., Setup, Maintenance, Production"
                        />
                    )}

                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={canBeCalledAsStep}
                                onChange={(e) => setCanBeCalledAsStep(e.target.checked)}
                                sx={{
                                    color: ConfigurationDataColors.Instance.primaryColor,
                                    '&.Mui-checked': {
                                        color: ConfigurationDataColors.Instance.primaryColor,
                                    },
                                }}
                            />
                        }
                        label={
                            <Box>
                                <Typography variant="body2">
                                    Can be called as step
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                    Allow this flow to be called from other flows
                                </Typography>
                            </Box>
                        }
                    />
                </Box>
            </DialogContent>

            <DialogActions sx={{ p: 3, pt: 2 }}>
                <Button
                    onClick={handleClose}
                    sx={{ color: ConfigurationDataColors.Instance.mutedTextColor }}
                >
                    Cancel
                </Button>
                <Button
                    onClick={handleCreate}
                    variant="contained"
                    disabled={!flowName.trim() || !!nameError}
                    sx={{
                        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        '&:hover': {
                            backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                            filter: 'brightness(0.9)',
                        },
                        '&:disabled': {
                            backgroundColor: ConfigurationDataColors.Instance.borderColor,
                            color: ConfigurationDataColors.Instance.mutedTextColor,
                        },
                    }}
                >
                    Create Flow
                </Button>
            </DialogActions>
        </Dialog>
    );
}