import { RotateRight as SpindleIcon } from '@mui/icons-material';
import { Box, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class StartSpindleStep extends FlowStep {
    readonly __type = 'StartSpindleStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Start Spindle';
    readonly description = 'Starts the spindle at specified speed';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SpindleIcon, { sx: { color: 'success.main' } });
    }

    // Step parameters
    public speed?: number;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return StartSpindleStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().spindle.StartSpindle(this.speed);
            return StartSpindleStep.DONE_PATH;
        } catch (error) {
            console.error('StartSpindle failed:', error);
            return StartSpindleStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [StartSpindleStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Start spindle{this.speed ? ` at ${this.speed} RPM` : ''}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const SpindleEditUI: React.FC = () => {
            const [speed, setSpeed] = useState(this.speed?.toString() || '');

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.speed = speed ? parseFloat(speed) : undefined;
            }, [speed]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <TextField
                        label="Speed (RPM, optional)"
                        type="number"
                        value={speed}
                        onChange={(e) => setSpeed(e.target.value)}
                        fullWidth
                        margin="normal"
                        helperText="Leave empty to use current speed setting"
                    />
                </Box>
            );
        };

        return React.createElement(SpindleEditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





