import { CallMade as RedirectIcon, Stop as StopIcon } from '@mui/icons-material';
import { Box, Button, List, ListItem, ListItemText, Typography } from '@mui/material';
import React from 'react';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { FlowStep } from "../FlowStep";
import { FlowStepData } from "../FlowStepData";

// Function component for the EndStep Edit UI
function EndStepUI({ endStep, flow, onClose }: { endStep: EndStep; flow: any; onClose: () => void }) {
    const [availableTargets, setAvailableTargets] = React.useState<FlowStep[]>([]);

    React.useEffect(() => {
        if (flow) {
            const targets = flow.getValidRedirectTargets(endStep.id);
            setAvailableTargets(targets);
        }
    }, [flow, endStep]);

    const handleRedirectClick = async (targetStep: FlowStep) => {
        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
            title: 'Redirect Flow',
            message: `Are you sure you want to redirect this flow to "${targetStep.customName || targetStep.name}"? This will remove the End step and connect the incoming path directly to the selected step.`,
            confirmText: 'Redirect',
            severity: 'warning'
        });

        if (confirmed && flow) {
            try {
                flow.redirectEndStep(endStep.id, targetStep.id);
                onClose(); // Close the edit dialog after redirect
                Logger.Instance.log(LogCategory.UserInterface, `Flow redirected to step: ${targetStep.customName || targetStep.name}`);
            } catch (error) {
                Logger.Instance.logError(LogCategory.UserInterface, 'Failed to redirect flow:', error);
            }
        }
    };

    return (
        <Box sx={{ p: 2, minWidth: 600, maxWidth: 800 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                <StopIcon sx={{ color: 'error.main' }} />
                <Typography variant="h6">Flow End Configuration</Typography>
            </Box>

            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                This step terminates the flow execution. Select a step below to redirect this flow to instead.
            </Typography>

            {availableTargets.length === 0 ? (
                <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                    No valid redirect targets available.
                </Typography>
            ) : (
                <List sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1, maxHeight: 500, overflow: 'auto' }}>
                    {availableTargets.map((step: FlowStep) => (
                        <ListItem
                            key={step.id}
                            secondaryAction={
                                <Button
                                    variant="contained"
                                    color="primary"
                                    size="small"
                                    startIcon={<RedirectIcon />}
                                    onClick={() => handleRedirectClick(step)}
                                >
                                    Redirect Here
                                </Button>
                            }
                        >
                            <ListItemText
                                primary={step.customName || step.name}
                                secondary={`${step.__type} - ${step.description}`}
                            />
                        </ListItem>
                    ))}
                </List>
            )}
        </Box>
    );
}



export class EndStep extends FlowStep {
    readonly __type = 'EndStep';
    readonly category = ['System'];
    readonly name = 'End';
    readonly description = 'Terminates flow execution';
    readonly canAdd = false; // End step cannot be added via dialog

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(StopIcon, { sx: { color: 'error.main' } });
    }

    // Static path constants
    static readonly COMPLETE_PATH = 'complete';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        // End step stops execution
        return null;
    }

    results(): string[] {
        return [EndStep.COMPLETE_PATH]; // End step completes the flow
    }

    renderStepUI(): React.ReactNode {
        return super.renderStepUI(); // Use default step UI
    }

    renderEditUI(props: { onClose: () => void, flow: any, flowStep?: any }): React.ReactNode {
        return <EndStepUI endStep={this} flow={props.flow} onClose={props.onClose} />;
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return null; // No UI for now
    }
}