import { Code as CodeIcon } from '@mui/icons-material';
import { Box, Checkbox, FormControlLabel, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class LoadGCodeStep extends FlowStep {
    readonly __type = 'LoadGCodeStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Run G-Code';
    readonly description = 'Runs G-Code program on the machine';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(CodeIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public gcode: string[] = [];
    public startImmediately: boolean = true;
    public gcodeParameterString: string = '';

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return LoadGCodeStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.RunGCode(this.gcode, this.startImmediately, this.gcodeParameterString);
            return LoadGCodeStep.DONE_PATH;
        } catch (error) {
            console.error('RunGCode failed:', error);
            return LoadGCodeStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [LoadGCodeStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Load G-code ({this.gcode.length} lines): {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const GCodeEditUI: React.FC = () => {
            const [gcodeText, setGcodeText] = useState(this.gcode.join('\n'));
            const [startImmediately, setStartImmediately] = useState(this.startImmediately);
            const [gcodeParameterString, setGcodeParameterString] = useState(this.gcodeParameterString);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.gcode = gcodeText.split('\n').filter(line => line.trim().length > 0);
            }, [gcodeText]);

            React.useEffect(() => {
                this.startImmediately = startImmediately;
            }, [startImmediately]);

            React.useEffect(() => {
                this.gcodeParameterString = gcodeParameterString;
            }, [gcodeParameterString]);

            return (
                <Box sx={{ p: 2, minWidth: 400 }}>
                    <TextField
                        label="G-Code"
                        multiline
                        rows={10}
                        value={gcodeText}
                        onChange={(e) => setGcodeText(e.target.value)}
                        fullWidth
                        margin="normal"
                        helperText="Enter G-code commands, one per line"
                        sx={{ fontFamily: 'monospace' }}
                    />
                    <TextField
                        label="G-Code Parameter String"
                        value={gcodeParameterString}
                        onChange={(e) => setGcodeParameterString(e.target.value)}
                        fullWidth
                        margin="normal"
                        helperText="Optional parameter string for G-code execution"
                    />
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={startImmediately}
                                onChange={(e) => setStartImmediately(e.target.checked)}
                            />
                        }
                        label="Start immediately after loading"
                    />
                </Box>
            );
        };

        return React.createElement(GCodeEditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





