import React from 'react';
import { Line } from '@react-three/drei';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { MachineData } from '../../../data/MachineData';
import { ConfigurationData } from '../../../data/ConfigurationData';

export function MachineZeroCrosshair() {
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: MachineData.Instance, properties: ['crosshairSize', 'crosshairLineWidth'] },
        { object: ConfigurationData.Instance, properties: ['machineZeroColor'] }
      ]}
      control={() => {
        const crosshairSize = MachineData.Instance.crosshairSize; // Use configurable size
        const lineWidth = MachineData.Instance.crosshairLineWidth; // Use configurable line width
        const color = ConfigurationData.Instance.machineZeroColor; // Use configurable color
        
        // Get machine zero position in simulator coordinates
        const machineZeroPos = CoordinateUtil.getMachineZeroPosition();
        const centerX = machineZeroPos.x;
        const centerY = machineZeroPos.y;
        const centerZ = machineZeroPos.z;

        return (
          <group>
            {/* X-axis line (red) */}
            <Line
              points={[
                [centerX - crosshairSize, centerY, centerZ],
                [centerX + crosshairSize, centerY, centerZ]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
            
            {/* Y-axis line (red) */}
            <Line
              points={[
                [centerX, centerY - crosshairSize, centerZ],
                [centerX, centerY + crosshairSize, centerZ]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
            
            {/* Z-axis line (red) */}
            <Line
              points={[
                [centerX, centerY, centerZ - crosshairSize],
                [centerX, centerY, centerZ + crosshairSize]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
          </group>
        );
      }}
    />
  );
}
