import React from 'react';
import { Cylinder } from '@react-three/drei';
import { ConfigurationData } from '../../../data/ConfigurationData';

interface ISO30ToolHolderProps {
  position: [number, number, number];
  toolClampHeight: number;
  armHeight: number;
  armDepth: number;
}

export function ISO30ToolHolder({ position, toolClampHeight, armHeight, armDepth }: ISO30ToolHolderProps) {
  const config = ConfigurationData.Instance;
  
  const [holderX, holderY, holderZ] = position;

  return (
    <group>
      {/* ISO30 Tool Holder Components (cylinder, cone, cylinder, sphere) */}
      
      {/* Bottom Cylinder (2 inch diameter to match clamp separation) */}
      <Cylinder
        position={[holderX, holderY - armDepth / 4, holderZ + (toolClampHeight - armHeight) / 2 - 0.5]}
        args={[1.0, 1.0, 1.0, 12]} // 2 inch diameter = 1 inch radius
        rotation={[Math.PI / 2, 0, 0]}
      >
        <meshPhongMaterial 
          color={config.toolHolderColor}
          transparent={true}
          opacity={0.9}
        />
      </Cylinder>

      {/* Conical Taper (ISO30 cone) */}
      <Cylinder
        position={[holderX, holderY - armDepth / 4, holderZ + (toolClampHeight - armHeight) / 2]}
        args={[0.6, 1.0, 0.8, 12]} // Tapers from 2" to 1.2" diameter
        rotation={[Math.PI / 2, 0, 0]}
      >
        <meshPhongMaterial 
          color={config.toolHolderColor}
          transparent={true}
          opacity={0.9}
        />
      </Cylinder>

      {/* Top Cylinder (smaller diameter) */}
      <Cylinder
        position={[holderX, holderY - armDepth / 4, holderZ + (toolClampHeight - armHeight) / 2 + 0.6]}
        args={[0.6, 0.6, 0.8, 12]} // 1.2 inch diameter
        rotation={[Math.PI / 2, 0, 0]}
      >
        <meshPhongMaterial 
          color={config.toolHolderColor}
          transparent={true}
          opacity={0.9}
        />
      </Cylinder>

      {/* Spherical End Cap */}
      <mesh position={[holderX, holderY - armDepth / 4, holderZ + (toolClampHeight - armHeight) / 2 + 1.0]}>
        <sphereGeometry args={[0.6, 16, 16]} />
        <meshPhongMaterial 
          color={config.toolHolderColor}
          transparent={true}
          opacity={0.9}
        />
      </mesh>
    </group>
  );
}
