import { Info as InfoIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetSystemInfoStep extends FlowStep {
    readonly __type = 'GetSystemInfoStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Get System Info';
    readonly description = 'Gets system information and configuration details';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(InfoIcon, { sx: { color: 'info.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            data.setVariable('systemInfo', { version: '1.0.0', status: 'prototype' });
            return GetSystemInfoStep.DONE_PATH;
        }

        try {
            const systemInfo = await Machine.getInstance().io.GetSystemInfo();
            data.setVariable('systemInfo', systemInfo);
            return GetSystemInfoStep.DONE_PATH;
        } catch (error) {
            console.error('GetSystemInfo failed:', error);
            data.setVariable('systemInfo', {});
            return GetSystemInfoStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [GetSystemInfoStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const systemInfo = data.getVariable('systemInfo') || {};
        const infoCount = Object.keys(systemInfo).length;
        return (
            <Typography variant="caption">
                Retrieved system info ({infoCount} properties)
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Get System Info</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step retrieves comprehensive system information including
                    configuration details, version information, and system status.
                    The result will be stored in the 'systemInfo' variable.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle2" gutterBottom>Information Includes:</Typography>
                    <Typography variant="body2">
                        • System version and build information
                    </Typography>
                    <Typography variant="body2">
                        • Hardware configuration details
                    </Typography>
                    <Typography variant="body2">
                        • Current system status
                    </Typography>
                    <Typography variant="body2">
                        • Available features and capabilities
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}