import React from 'react';
import { 
  Box, 
  Typography, 
  CircularProgress, 
  Paper,
  Alert
} from '@mui/material';
import { ObserveState } from '../utils/statemanager/ObserveState';
import { AppStateData } from '../data/AppStateData';
import { ConfigurationData } from '../data/ConfigurationData';

/**
 * LoadingSplashScreen displays while the application is initializing data
 * Shows loading spinner, progress messages, and error states if initialization fails
 */
export function LoadingSplashScreen() {
  const config = ConfigurationData.Instance;
  
  return (
    <ObserveState
      listenTo={AppStateData.Instance}
      properties={['isLoading', 'loadingMessage', 'initializationError']}
      control={() => {
        const appState = AppStateData.Instance;
        
        return (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              height: '100vh',
              backgroundColor: config.lightBackgroundColor,
              padding: 3
            }}
          >
            <Paper
              elevation={8}
              sx={{
                padding: 6,
                borderRadius: 4,
                textAlign: 'center',
                maxWidth: 500,
                width: '100%',
                backgroundColor: config.darkBackgroundColor,
                color: config.lightTextColor
              }}
            >
              {/* App Title */}
              <Typography 
                variant="h3" 
                component="h1" 
                gutterBottom
                sx={{ 
                  color: config.primaryColor,
                  fontWeight: 'bold',
                  marginBottom: 3
                }}
              >
                HavenCNC
              </Typography>
              
              {/* Loading State */}
              {appState.isLoading && !appState.initializationError && (
                <>
                  <CircularProgress 
                    size={60} 
                    sx={{ 
                      color: config.primaryColor,
                      marginBottom: 3
                    }} 
                  />
                  <Typography 
                    variant="h6" 
                    sx={{ 
                      color: config.lightTextColor,
                      marginBottom: 1
                    }}
                  >
                    {appState.loadingMessage}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      color: config.mutedTextColor
                    }}
                  >
                    Initializing configuration and machine data...
                  </Typography>
                </>
              )}
              
              {/* Error State */}
              {appState.initializationError && (
                <Alert 
                  severity="error" 
                  sx={{ 
                    marginTop: 2,
                    backgroundColor: config.errorColor + '20',
                    color: config.lightTextColor,
                    '& .MuiAlert-icon': {
                      color: config.errorColor
                    }
                  }}
                >
                  <Typography variant="h6" gutterBottom>
                    Initialization Failed
                  </Typography>
                  <Typography variant="body2">
                    {appState.initializationError}
                  </Typography>
                  <Typography variant="body2" sx={{ marginTop: 1, fontStyle: 'italic' }}>
                    The application will continue with default settings.
                  </Typography>
                </Alert>
              )}
              
              {/* Success State (brief display before main UI loads) */}
              {!appState.isLoading && !appState.initializationError && appState.isInitialized && (
                <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                  <Typography 
                    variant="h6" 
                    sx={{ 
                      color: config.successColor,
                      marginBottom: 2
                    }}
                  >
                    ✓ Initialization Complete
                  </Typography>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      color: config.mutedTextColor
                    }}
                  >
                    Loading main interface...
                  </Typography>
                </Box>
              )}
            </Paper>
            
            {/* Version Info */}
            <Typography 
              variant="caption" 
              sx={{ 
                color: config.mutedTextColor,
                marginTop: 3,
                textAlign: 'center'
              }}
            >
              CNC Machine Control Interface
              <br />
              React/TypeScript with Three.js Visualization
            </Typography>
          </Box>
        );
      }}
    />
  );
}
