import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, Typography } from '@mui/material';
import { useState } from 'react';
import { Fixture, FixtureLibrary, FixtureType } from '../../data/Common/FixtureLibrary';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { CoordinateOperations } from '../../utils/CoordinateOperations';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { FixtureNameInputDialog } from '../Common/FixtureNameInputDialog';
import { FixtureSelectionDialog } from '../Common/FixtureSelectionDialog';
import { MessageViewer } from '../Common/MessageViewer';
import { NumberInput } from '../Common/NumberInput';
import { SafeModeControl } from '../Common/SafeModeControl';
import { ToolSelectionDialog } from '../Common/ToolSelectionDialog';
import { CNCViewType } from '../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';
import { ClampEditorForm } from './ClampEditorForm';
import { MaterialEditor } from './MaterialEditor';

interface HomeProps {
  onViewChange?: (view: string) => void;
}

export function Home({ onViewChange }: HomeProps) {
  const [config] = useState(() => ConfigurationData.Instance);
  const [machineState] = useState(() => MachineStateData.Instance);
  const [machineData] = useState(() => MachineData.Instance);
  const [simulatorView] = useState(() => new SimulatorView());
  const [materialEditorOpen, setMaterialEditorOpen] = useState(false);
  const [clampEditorOpen, setClampEditorOpen] = useState(false);
  const [fixtureDialogOpen, setFixtureDialogOpen] = useState(false);
  const [fixtureNameDialogOpen, setFixtureNameDialogOpen] = useState(false);
  const [toolDialogOpen, setToolDialogOpen] = useState(false);
  const [toolLibrary] = useState(() => ToolLibrary.Instance);

  const handleSaveFixturePosition = (name: string, useCurrentLocation: boolean) => {
    const currentFixture = ConfigurationState.Instance.currentFixture;
    const toolOffsets = machineState.currentToolOffsets;

    let x: number, y: number, z: number;

    if (useCurrentLocation) {
      const currentPoint = machineState.currentMachinePoint;
      x = currentPoint.x - toolOffsets.x;
      y = currentPoint.y - toolOffsets.y;
      z = currentPoint.z - toolOffsets.z;
    } else {
      if (!currentFixture) {
        UserMessageQueue.Instance.addMessage('❌ No current fixture selected');
        return;
      }

      const currentPoint = machineState.currentMachinePoint;
      currentFixture.xOffset = currentPoint.x - toolOffsets.x;
      currentFixture.yOffset = currentPoint.y - toolOffsets.y;
      currentFixture.zOffset = currentPoint.z - toolOffsets.z;

      UserMessageQueue.Instance.addMessage(`✓ Saved ${currentFixture.name} fixture position`);
      return;
    }

    const newFixture = new Fixture(
      name,
      name,
      x,
      y,
      z,
      false,
      FixtureType.SavedPoint,
      true
    );
    FixtureLibrary.Instance.addFixture(newFixture);

    UserMessageQueue.Instance.addMessage(`✓ Created known point "${name}" from current location`);
  };

  const getExistingFixtureNames = (): string[] => {
    return FixtureLibrary.Instance.fixtures.map(f => f.name);
  };

  const handleCoordinateChange = (axis: string, value: number) => {
    CoordinateOperations.setProposedCoordinate(axis, value);
  };

  const getButtonType = (axis: string): string | null => {
    // Show Go button if this specific axis has a proposed position that differs
    if (CoordinateOperations.hasProposedPositionForAxis(axis)) {
      return 'go';
    }

    // Check if we should show Set button based on work coordinate value
    const currentMachinePos = machineState.currentMachinePoint;
    const workCoordinates = CoordinateUtil.toWorkZero(currentMachinePos);

    // Get the work coordinate for the axis
    let workCoordinate: number;
    switch (axis) {
      case 'X':
        workCoordinate = workCoordinates.x;
        break;
      case 'Y':
        workCoordinate = workCoordinates.y;
        break;
      case 'Z':
        workCoordinate = workCoordinates.z;
        break;
      case 'A':
        workCoordinate = 0; // A-axis placeholder - treat as always at zero for now
        break;
      default:
        return null;
    }

    // If work coordinate is close to 0, don't show Set button
    const tolerance = 0.001;
    const isAtWorkZero = Math.abs(workCoordinate) < tolerance;

    if (isAtWorkZero) {
      return null; // No button when work coordinate is 0
    }

    return 'set'; // Show Set button when work coordinate is not 0
  };

  const handleSetWorkZero = (axis: string) => {
    CoordinateOperations.setWorkZero(axis);
  };

  const handleGoToPosition = (axis: string) => {
    const proposedPosition = machineState.proposedSpindlePosition;
    if (!proposedPosition) return;

    // Create move action with the proposed position
    const moveAction = MoveAction.fromCNCPoint(proposedPosition, MoveType.Coordinates);
    ActionBus.Instance.addAction(moveAction);

    // Note: proposedSpindlePosition is cleared by MoveAction when canceled or completed
  };

  return (
    <Box sx={{ height: '100%', display: 'grid', gridTemplateColumns: '1fr 1fr', gridTemplateRows: '1fr 1fr', gap: 2, p: 2 }}>
      {/* Top Left: Coordinates and Safe Mode */}
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, minHeight: 0, overflow: 'auto' }}>
        {/* Coordinate Display with Action Buttons */}
        <Box sx={{ display: 'flex', gap: 2 }}>
          {/* Coordinates Column */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <ObserveState
              key="home-coordinates-observer"
              listenTo={machineState}
              properties={['currentMachinePoint', 'currentWorkZero', 'currentToolOffsets', 'currentToolNumber', 'proposedSpindlePosition']}
              control={() => {
                return (
                  <>
                    {/* Large Coordinate Displays with NumberInput */}
                    {['X', 'Y', 'Z', 'A'].map((axis) => {
                      const displayValue = CoordinateOperations.getDisplayCoordinate(axis);
                      const buttonType = getButtonType(axis);
                      const hasProposedForAxis = CoordinateOperations.hasProposedPositionForAxis(axis);

                      return (
                        <Box key={axis} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                          <Typography sx={{ minWidth: '40px', fontSize: '1.5rem', fontWeight: 'bold' }}>
                            {axis}:
                          </Typography>
                          <NumberInput
                            value={displayValue}
                            onChange={(value) => handleCoordinateChange(axis, value)}
                            precision={3}
                            allowNegative={true}
                            allowPositive={true}
                            allowFractions={true}
                            showHelperText={false}
                            beforeText={`Work coordinate ${axis} - position relative to work zero`}
                            afterText="Press Enter/Tab to move, or use Set button to set work zero to current position."
                            disabled={false}
                            size="medium"
                            variant="outlined"
                            textColor={hasProposedForAxis ? config.successColor : undefined}
                            sx={{
                              width: '200px',
                              '& .MuiOutlinedInput-input': {
                                fontFamily: 'monospace',
                                fontSize: '2.5rem',
                                fontWeight: 'bold',
                                padding: '12px 16px',
                                textAlign: 'right'
                              },
                              '& .MuiOutlinedInput-root': {
                                backgroundColor: config.lightTextColor,
                                borderWidth: '2px',
                                borderColor: config.borderColor,
                              }
                            }}
                          />
                          {buttonType && (
                            <Box
                              sx={{
                                width: '80px',
                                height: '56px',
                                backgroundColor: config.primaryColor,
                                color: config.lightTextColor,
                                border: 'none',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                fontSize: '1rem',
                                fontWeight: 'bold',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                '&:hover': {
                                  opacity: 0.9
                                }
                              }}
                              component="button"
                              onClick={() => buttonType === 'set' ? handleSetWorkZero(axis) : handleGoToPosition(axis)}
                            >
                              {buttonType === 'set' ? 'Set' : 'Go'}
                            </Box>
                          )}
                        </Box>
                      );
                    })}
                  </>
                );
              }}
            />
          </Box>

          {/* Action Buttons Column */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, minWidth: '200px' }}>
            <ObserveState
              key="home-change-fixture-button"
              listenTo={ConfigurationState.Instance}
              properties={['currentFixture']}
              control={() => {
                const currentFixture = ConfigurationState.Instance.currentFixture;
                const fixtureLabel = currentFixture?.fixtureNumber || 'None';

                return (
                  <Box
                    component="button"
                    sx={{
                      width: '100%',
                      padding: '4px 8px',
                      backgroundColor: 'transparent',
                      color: config.primaryColor,
                      border: 'none',
                      cursor: 'pointer',
                      fontSize: '0.9rem',
                      fontWeight: 'normal',
                      textAlign: 'left',
                      textDecoration: 'underline',
                      '&:hover': {
                        textDecoration: 'none',
                        fontWeight: 'bold'
                      }
                    }}
                    onClick={() => setFixtureDialogOpen(true)}
                  >
                    Change Fixture ({fixtureLabel})
                  </Box>
                );
              }}
            />
            <Box
              component="button"
              sx={{
                width: '100%',
                padding: '4px 8px',
                backgroundColor: 'transparent',
                color: config.primaryColor,
                border: 'none',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: 'normal',
                textAlign: 'left',
                textDecoration: 'underline',
                '&:hover': {
                  textDecoration: 'none',
                  fontWeight: 'bold'
                }
              }}
              onClick={() => setFixtureNameDialogOpen(true)}
            >
              Remember Point
            </Box>
            <Box
              component="button"
              sx={{
                width: '100%',
                padding: '4px 8px',
                backgroundColor: 'transparent',
                color: config.primaryColor,
                border: 'none',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: 'normal',
                textAlign: 'left',
                textDecoration: 'underline',
                '&:hover': {
                  textDecoration: 'none',
                  fontWeight: 'bold'
                }
              }}
              onClick={() => setMaterialEditorOpen(true)}
            >
              Edit Material
            </Box>
            <Box
              component="button"
              sx={{
                width: '100%',
                padding: '4px 8px',
                backgroundColor: 'transparent',
                color: config.primaryColor,
                border: 'none',
                cursor: 'pointer',
                fontSize: '0.9rem',
                fontWeight: 'normal',
                textAlign: 'left',
                textDecoration: 'underline',
                '&:hover': {
                  textDecoration: 'none',
                  fontWeight: 'bold'
                }
              }}
              onClick={() => setClampEditorOpen(true)}
            >
              Edit Clamps
            </Box>

            {/* Current Tool Display with Change Link */}
            <Box
              sx={{
                mt: 1,
                p: 1.5,
                border: 1,
                borderColor: config.borderColor,
                borderRadius: 1,
                position: 'relative'
              }}
            >
              {/* Label on border */}
              <Typography
                variant="body2"
                sx={{
                  position: 'absolute',
                  top: -8,
                  left: 8,
                  backgroundColor: 'background.paper',
                  px: 0.5,
                  color: config.mutedTextColor,
                  fontSize: '0.75rem',
                  fontWeight: 'normal'
                }}
              >
                Current Tool
              </Typography>

              {/* Tool display and change link */}
              <ObserveState
                key="home-current-tool-content"
                listenTo={machineState}
                properties={['currentToolNumber']}
                control={() => {
                  const currentToolNumber = machineState.currentToolNumber;
                  const tool = toolLibrary.tools.find(t => t.toolNumber === currentToolNumber);
                  const toolLabel = tool ? `T${tool.toolNumber.toString().padStart(2, '0')} - ${tool.displayName}` : 'None';

                  return (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                      <Typography
                        sx={{
                          fontSize: '0.9rem',
                          fontWeight: 'normal',
                          color: config.darkTextColor
                        }}
                      >
                        {toolLabel}
                      </Typography>
                      <Box
                        component="button"
                        sx={{
                          width: '100%',
                          padding: '2px 0',
                          backgroundColor: 'transparent',
                          color: config.primaryColor,
                          border: 'none',
                          cursor: 'pointer',
                          fontSize: '0.85rem',
                          fontWeight: 'normal',
                          textAlign: 'left',
                          textDecoration: 'underline',
                          '&:hover': {
                            textDecoration: 'none',
                            fontWeight: 'bold'
                          }
                        }}
                        onClick={() => setToolDialogOpen(true)}
                      >
                        Change Tool
                      </Box>
                    </Box>
                  );
                }}
              />
            </Box>
          </Box>
        </Box>

        {/* Safe Mode Controls */}
        <SafeModeControl />
      </Box>

      {/* Top Right: Message Viewer */}
      <Box sx={{ minHeight: 0, overflow: 'hidden', borderBottom: `1px solid ${config.borderColor}` }}>
        <MessageViewer />
      </Box>

      {/* Bottom Left: 3D Machine Viewer */}
      <Box sx={{ minHeight: 0, overflow: 'hidden' }}>
        <FullSizeCNCViewer
          simulatorView={simulatorView}
          machineState={machineState}
          machineData={machineData}
          job={machineState.currentJob || Job.createTestJob()}
          viewType={CNCViewType.Perspective}
          enableOrbit={true}
          enableClampDragging={false}
          enableSpindleDrag={false}
        />
      </Box>

      {/* Bottom Right: Blank for now */}
      <Box sx={{ minHeight: 0, overflow: 'hidden', p: 2, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Typography variant="h6" color="text.secondary">
          Reserved for future content
        </Typography>
      </Box>

      {/* Material Editor Dialog */}
      <MaterialEditor
        open={materialEditorOpen}
        onClose={() => setMaterialEditorOpen(false)}
        machineState={machineState}
      />

      {/* Clamp Editor Dialog */}
      <Dialog
        open={clampEditorOpen}
        onClose={() => setClampEditorOpen(false)}
        maxWidth="lg"
        fullWidth
        PaperProps={{
          sx: { height: '80vh' }
        }}
      >
        <DialogTitle>Clamp Setup</DialogTitle>
        <DialogContent sx={{ p: 2, height: 'calc(100% - 120px)', overflow: 'auto' }}>
          <ClampEditorForm
            onSaveToLibrary={() => {
              // Save to library implementation
            }}
            onLoadFromLibrary={() => {
              // Load from library implementation
            }}
            height="100%"
          />
        </DialogContent>
        <DialogActions sx={{ p: 2, justifyContent: 'flex-end' }}>
          <Button onClick={() => setClampEditorOpen(false)} variant="contained">
            Done
          </Button>
        </DialogActions>
      </Dialog>

      {/* Fixture Selection Dialog */}
      <FixtureSelectionDialog
        open={fixtureDialogOpen}
        onClose={() => setFixtureDialogOpen(false)}
      />

      {/* Fixture Name Input Dialog */}
      <FixtureNameInputDialog
        open={fixtureNameDialogOpen}
        onClose={() => setFixtureNameDialogOpen(false)}
        onSave={handleSaveFixturePosition}
        currentFixtureName={ConfigurationState.Instance.currentFixture?.fixtureNumber || ''}
        existingNames={getExistingFixtureNames()}
      />

      {/* Tool Selection Dialog */}
      <ToolSelectionDialog
        open={toolDialogOpen}
        onClose={() => setToolDialogOpen(false)}
      />
    </Box>
  );
}
