import React from "react";
import { Box, Typography, Button, Alert } from '@mui/material';
import { CheckCircle as CheckIcon } from '@mui/icons-material';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { ZAxisReferenceType, TouchOffMethod } from '../common/types';
import { ConfigurationData } from '../../../../data/ConfigurationData';

export class ResultsStep extends BaseWizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "Done", "");
    this.backButtonText = ""; // Hide back button on results
  }

  getTitle(): string {
    return "Z-Axis Calibration Complete";
  }

  nextStep(): WizardStep | null {
    return null; // Close wizard
  }

  private getReferenceTitle(): string {
    switch (this.wizard.state.referenceType) {
      case ZAxisReferenceType.BED:
        return 'Machine Bed';
      case ZAxisReferenceType.SPOILBOARD:
        return 'Spoilboard';
      case ZAxisReferenceType.MATERIAL:
        return 'Material Surface';
      default:
        return 'Surface';
    }
  }

  private getMethodTitle(): string {
    switch (this.wizard.state.method) {
      case TouchOffMethod.TOUCHPLATE:
        return 'Touch Plate';
      case TouchOffMethod.MANUAL:
        return 'Manual Positioning';
      default:
        return 'Unknown';
    }
  }

  render(): React.ReactNode {
    const method = this.wizard.state.method;
    const finalZPosition = this.wizard.state.finalZPosition || 0;
    const touchplateThickness = this.wizard.state.touchplateThickness || 0;
    const isManual = method === TouchOffMethod.MANUAL;
    const config = ConfigurationData.Instance;
    
    return (
      <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 2, minHeight: 400 }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 2 }}>
          <CheckIcon sx={{ fontSize: 80, color: 'success.main' }} />
          <Typography variant="h4" color="success.main" textAlign="center">
            {isManual ? 'Position Set Successfully!' : 'Calibration Complete!'}
          </Typography>
        </Box>

        <Alert severity="success" sx={{ mb: 2 }}>
          <Typography variant="h6" gutterBottom>
            {isManual ? 'Manual positioning completed' : 'Touch-off calibration completed'}
          </Typography>
          <Typography variant="body2">
            {isManual 
              ? `The Z-axis has been manually set to the ${this.getReferenceTitle().toLowerCase()}.`
              : `The Z-axis has been automatically calibrated using the touch plate to the ${this.getReferenceTitle().toLowerCase()}.`
            }
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
          <Typography variant="h6" color="text.primary">
            Calibration Results:
          </Typography>
          <Box sx={{ ml: 2 }}>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Final Z Position:</strong> {finalZPosition.toFixed(3)}" from machine zero
            </Typography>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Reference Surface:</strong> {this.getReferenceTitle()}
            </Typography>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Method:</strong> {this.getMethodTitle()}
            </Typography>
            {!isManual && touchplateThickness > 0 && (
              <Typography variant="body2" paragraph sx={{ mb: 1 }}>
                ✓ <strong>Touch Plate Thickness:</strong> {touchplateThickness.toFixed(3)}"
              </Typography>
            )}
          </Box>
        </Box>

        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="body2">
            <strong>Tip:</strong> Your Z-axis reference has been saved and will be used for all subsequent operations. 
            You can recalibrate at any time using the touch-off wizard.
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 'auto', pt: 2 }}>
          <Button
            variant="contained"
            size="large"
            onClick={() => this.wizard.closeWizard()}
            sx={{ 
              backgroundColor: config.primaryColor,
              minWidth: 200,
              py: 1.5
            }}
          >
            Done
          </Button>
        </Box>
      </Box>
    );
  }
}
