import React, { useState, useCallback } from 'react';
import {
  Typography,
  Box,
  Paper,
  TextField,
  Button,
  Alert,
  InputAdornment,
  IconButton
} from '@mui/material';
import {
  Security,
  Visibility,
  VisibilityOff
} from '@mui/icons-material';
import { SystemSetupPanel } from '../Layout/SystemSetupPanel';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { SYSTEM_CONFIG_PIN } from '../../data/Common/SystemConfiguration';
import { Logger, LogCategory } from '../../utils/Logger';
import { UserMessageQueue } from '../../data/UserMessageQueue';

export function System() {
  const [pin, setPin] = useState('');
  const [showPin, setShowPin] = useState(false);
  const [pinError, setPinError] = useState('');

  const handlePinSubmit = useCallback(() => {
    if (pin === SYSTEM_CONFIG_PIN) {
      ConfigurationData.Instance.systemConfigurationUnlocked = true;
      UserMessageQueue.Instance.addMessage('✓ System configuration unlocked');
      //Logger.Instance.log(LogCategory.System, 'System configuration unlocked');
      setPin('');
      setPinError('');
    } else {
      setPinError('Invalid PIN');
      Logger.Instance.logError(LogCategory.System, 'Invalid PIN attempt for system configuration');
    }
  }, [pin]);

  const handlePinKeyPress = useCallback((event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      handlePinSubmit();
    }
  }, [handlePinSubmit]);
  return (
    <ObserveState
      listenTo={ConfigurationData.Instance}
      properties={['systemConfigurationUnlocked']}
      control={() => {
        const config = ConfigurationData.Instance;
        
        if (!config.systemConfigurationUnlocked) {
          return (
            <Box sx={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Paper sx={{ p: 4, textAlign: 'center', maxWidth: 400 }}>
                <Security sx={{ fontSize: 48, color: 'warning.main', mb: 2 }} />
                <Typography variant="h5" gutterBottom color="warning.main">
                  System Configuration Locked
                </Typography>
                <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                  <br />
                  Enter PIN to access system configuration.
                </Typography>
                
                <TextField
                  label="PIN"
                  type={showPin ? 'text' : 'password'}
                  value={pin}
                  onChange={(e) => setPin(e.target.value)}
                  onKeyPress={handlePinKeyPress}
                  error={!!pinError}
                  helperText={pinError}
                  fullWidth
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          onClick={() => setShowPin(!showPin)}
                          edge="end"
                        >
                          {showPin ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={{ mb: 2 }}
                />
                
                <Button
                  variant="contained"
                  onClick={handlePinSubmit}
                  fullWidth
                  disabled={!pin}
                  sx={{ mb: 2 }}
                >
                  Unlock System Configuration
                </Button>
                
                <Alert severity="info" sx={{ textAlign: 'left' }}>
                  <Typography variant="caption">
                    For development use only. Production systems should use secure authentication.
                  </Typography>
                </Alert>
              </Paper>
            </Box>
          );
        }

        return (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <SystemSetupPanel />
          </Box>
        );
      }}
    />
  );
}
