import {
  Box,
  Button,
  Divider
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveMultiState } from '../../utils/statemanager/ObserveMultiState';
import { CNCViewer } from '../MachineViewer/CNCViewer';
import { ClampLibraryTab, ConfigCheckpointsTab, ConfigurationTab, FixtureLibraryTab, MachineStateTab, MaterialLibraryTab, ToolLibraryTab } from './Settings/';

interface SettingsTabButtonProps {
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const SettingsTabButton: React.FC<SettingsTabButtonProps> = ({ label, isActive, onClick }) => (
  <Button
    variant={isActive ? 'contained' : 'text'}
    onClick={onClick}
    sx={{
      mx: 1,
      minWidth: '120px',
      textTransform: 'none',
      fontSize: '14px'
    }}
  >
    {label}
  </Button>
);

type SettingsTab = 'machinestate' | 'configuration' | 'materials' | 'tools' | 'clamps' | 'fixtures' | 'checkpoints';

export const Settings: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('configuration');

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'machinestate':
        return <MachineStateTab />;
      case 'configuration':
        return <ConfigurationTab />;
      case 'materials':
        return <MaterialLibraryTab />;
      case 'tools':
        return <ToolLibraryTab />;
      case 'clamps':
        return <ClampLibraryTab />;
      case 'fixtures':
        return <FixtureLibraryTab />;
      case 'checkpoints':
        return <ConfigCheckpointsTab />;
      default:
        return <ConfigurationTab />;
    }
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Tab Navigation */}
      <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', backgroundColor: 'background.paper' }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>

          <SettingsTabButton
            label="Machine State"
            isActive={activeTab === 'machinestate'}
            onClick={() => setActiveTab('machinestate')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Configuration"
            isActive={activeTab === 'configuration'}
            onClick={() => setActiveTab('configuration')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Materials"
            isActive={activeTab === 'materials'}
            onClick={() => setActiveTab('materials')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Tools"
            isActive={activeTab === 'tools'}
            onClick={() => setActiveTab('tools')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Clamps"
            isActive={activeTab === 'clamps'}
            onClick={() => setActiveTab('clamps')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Fixtures/Known Points"
            isActive={activeTab === 'fixtures'}
            onClick={() => setActiveTab('fixtures')}
          />

          <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

          <SettingsTabButton
            label="Checkpoints"
            isActive={activeTab === 'checkpoints'}
            onClick={() => setActiveTab('checkpoints')}
          />
        </Box>
      </Box>

      {/* Main Content - Split Layout */}
      <Box sx={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
        {/* Settings Panel - 60% */}
        <Box sx={{ width: '60%', overflow: 'auto' }}>
          {renderActiveTab()}
        </Box>

        {/* 3D Viewer Panel - 40% */}
        <Box sx={{
          width: '40%',
          borderLeft: 1,
          borderColor: 'divider',
          position: 'relative',
          overflow: 'hidden'
        }}>
          <Box sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: ConfigurationData.Instance.lightBackgroundColor
          }}>
            <ObserveMultiState
              listenTo={[ConfigurationData.Instance, MachineData.Instance]}
              control={() => (
                <CNCViewer
                  simulatorView={ConfigurationData.Instance.defaultView}
                  machineState={MachineStateData.Instance}
                  machineData={MachineData.Instance}
                  job={MachineStateData.Instance.currentJob || Job.createTestJob()}
                  isHardcodedSettings={false}
                />
              )}
            />
          </Box>
        </Box>
      </Box>
    </Box>
  );
};
