import {
    Delete as DeleteIcon,
    Edit as EditIcon,
    Refresh as RefreshIcon,
    PlayArrow as RunIcon,
    Save as SaveIcon
} from '@mui/icons-material';
import {
    Alert,
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    FormControlLabel,
    Grid,
    IconButton,
    List,
    ListItemButton,
    ListItemSecondaryAction,
    ListItemText,
    Paper,
    Switch,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Storage, StorageType } from '../../machine/ICNCProgramStorage';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface SaveDialogProps {
    open: boolean;
    onClose: () => void;
    onSave: (name: string, categoryName: string, exposeAsAction: boolean) => void;
    initialName?: string;
    initialCategoryName?: string;
    initialExposeAsAction?: boolean;
}

const SaveDialog: React.FC<SaveDialogProps> = ({
    open,
    onClose,
    onSave,
    initialName = '',
    initialCategoryName = '',
    initialExposeAsAction = false
}) => {
    const [name, setName] = useState(initialName);
    const [categoryName, setCategoryName] = useState(initialCategoryName);
    const [exposeAsAction, setExposeAsAction] = useState(initialExposeAsAction);

    useEffect(() => {
        setName(initialName);
        setCategoryName(initialCategoryName);
        setExposeAsAction(initialExposeAsAction);
    }, [initialName, initialCategoryName, initialExposeAsAction]);

    const handleSave = () => {
        if (!name.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter a name for the MDI command');
            return;
        }

        if (exposeAsAction && !categoryName.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter a category name when exposing as action');
            return;
        }

        onSave(name.trim(), categoryName.trim(), exposeAsAction);
        onClose();
    };

    const config = ConfigurationData.Instance;

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>Save MDI Command</DialogTitle>
            <DialogContent>
                <TextField
                    fullWidth
                    label="Command Name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    margin="normal"
                    placeholder="e.g., 'Quick Home', 'Tool Change Position'"
                />

                <FormControlLabel
                    control={
                        <Switch
                            checked={exposeAsAction}
                            onChange={(e) => setExposeAsAction(e.target.checked)}
                            sx={{
                                '& .MuiSwitch-switchBase.Mui-checked': {
                                    color: config.primaryColor,
                                },
                                '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                                    backgroundColor: config.primaryColor,
                                },
                            }}
                        />
                    }
                    label="Expose as Action Button"
                    sx={{ mt: 2, mb: 1 }}
                />

                {exposeAsAction && (
                    <TextField
                        fullWidth
                        label="Category Name"
                        value={categoryName}
                        onChange={(e) => setCategoryName(e.target.value)}
                        margin="normal"
                        placeholder="e.g., 'Home All Axes', 'Move to Tool Change'"
                        helperText="This name will appear on action buttons throughout the application"
                    />
                )}
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose}>Cancel</Button>
                <Button
                    onClick={handleSave}
                    variant="contained"
                    sx={{
                        backgroundColor: config.primaryColor,
                        '&:hover': {
                            backgroundColor: config.primaryColor,
                            opacity: 0.8
                        }
                    }}
                >
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export function MDIView() {
    const [gcode, setGcode] = useState('');
    const [savedCommands, setSavedCommands] = useState<Storage[]>([]);
    const [saveDialogOpen, setSaveDialogOpen] = useState(false);
    const [editingCommand, setEditingCommand] = useState<Storage | null>(null);
    const [isRunning, setIsRunning] = useState(false);

    const loadSavedCommands = async () => {
        try {
            const machine = Machine.getInstance();
            const names = await machine.storage.getMDIStorageNames();
            const commands: Storage[] = [];

            for (const name of names) {
                const storage = await machine.storage.getStorageData(name);
                if (storage) {
                    commands.push(storage);
                }
            }

            setSavedCommands(commands.sort((a, b) => a.name.localeCompare(b.name)));
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to load saved MDI commands:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load saved commands');
        }
    };

    useEffect(() => {
        loadSavedCommands();
    }, []);

    const handleRun = async () => {
        if (!gcode.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter G-code to run');
            return;
        }

        try {
            setIsRunning(true);
            const machine = Machine.getInstance();
            const gcodeLines = gcode.split('\n').filter(line => line.trim());

            Logger.Instance.log(LogCategory.UserInterface, `Running MDI command: ${gcodeLines.length} lines`);
            await machine.program.RunGCode(gcodeLines);

            UserMessageQueue.Instance.addMessage('✓ MDI command executed successfully');
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to run MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to execute MDI command');
        } finally {
            setIsRunning(false);
        }
    };

    const handleSave = async (name: string, categoryName: string, exposeAsAction: boolean) => {
        if (!gcode.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter G-code to save');
            return;
        }

        try {
            const machine = Machine.getInstance();
            const storage = new Storage();
            storage.name = name;
            storage.data = gcode.trim();
            storage.storageType = StorageType.MDI;
            storage.exposeAsAction = exposeAsAction;
            storage.categoryName = exposeAsAction ? categoryName : '';
            storage.createdAt = editingCommand ? editingCommand.createdAt : new Date();
            storage.updatedAt = new Date();

            await machine.storage.saveStorageData(storage);

            UserMessageQueue.Instance.addMessage('✓ MDI command saved successfully');
            await loadSavedCommands();
            setEditingCommand(null);
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to save MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to save MDI command');
        }
    };

    const handleLoad = (command: Storage) => {
        setGcode(command.data);
        setEditingCommand(command);
        UserMessageQueue.Instance.addMessage(`✓ Loaded command: ${command.name}`);
    };

    const handleEdit = (command: Storage) => {
        setGcode(command.data);
        setEditingCommand(command);
        setSaveDialogOpen(true);
    };

    const handleDelete = async (command: Storage) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`MDI command "${command.name}"`);
        if (!confirmed) return;

        try {
            const machine = Machine.getInstance();
            await machine.storage.deleteStorageData(command.name);

            UserMessageQueue.Instance.addMessage('✓ MDI command deleted successfully');
            await loadSavedCommands();

            // Clear editor if we were editing this command
            if (editingCommand?.name === command.name) {
                setGcode('');
                setEditingCommand(null);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to delete MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to delete MDI command');
        }
    };

    const handleNew = () => {
        setGcode('');
        setEditingCommand(null);
        UserMessageQueue.Instance.addMessage('✓ New MDI command ready');
    };

    return (
        <ObserveState
            key="mdi-view"
            listenTo={ConfigurationData.Instance}
            properties={['primaryColor', 'backgroundColor', 'textColor', 'borderColor']}
            control={() => {
                const config = ConfigurationData.Instance;

                return (
                    <Box sx={{ p: 3, height: '100%', overflow: 'auto' }}>
                        <Typography variant="h4" gutterBottom sx={{ color: config.primaryColor }}>
                            MDI (Manual Data Input)
                        </Typography>

                        <Grid container spacing={3} sx={{ height: 'calc(100% - 80px)' }}>
                            {/* Left Panel - G-code Editor */}
                            <Grid item xs={12} md={8}>
                                <Paper sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                        <Typography variant="h6">G-code Command</Typography>
                                        <Button
                                            variant="outlined"
                                            onClick={handleNew}
                                            size="small"
                                        >
                                            New
                                        </Button>
                                    </Box>

                                    {editingCommand && (
                                        <Alert severity="info" sx={{ mb: 2 }}>
                                            Editing: <strong>{editingCommand.name}</strong>
                                            {editingCommand.exposeAsAction && ` (Category: ${editingCommand.categoryName})`}
                                        </Alert>
                                    )}

                                    <TextField
                                        fullWidth
                                        multiline
                                        variant="outlined"
                                        value={gcode}
                                        onChange={(e) => setGcode(e.target.value)}
                                        placeholder="Enter G-code commands here...&#10;Example:&#10;G0 X0 Y0 Z5&#10;G1 X10 Y10 F100"
                                        sx={{
                                            flex: 1,
                                            '& .MuiInputBase-inputMultiline': {
                                                fontFamily: 'monospace',
                                                fontSize: '14px'
                                            }
                                        }}
                                    />

                                    <Box sx={{ display: 'flex', gap: 2, mt: 2 }}>
                                        <Button
                                            variant="contained"
                                            startIcon={<RunIcon />}
                                            onClick={handleRun}
                                            disabled={isRunning || !gcode.trim()}
                                            sx={{
                                                backgroundColor: config.primaryColor,
                                                '&:hover': {
                                                    backgroundColor: config.primaryColor,
                                                    opacity: 0.8
                                                }
                                            }}
                                        >
                                            {isRunning ? 'Running...' : 'Run'}
                                        </Button>

                                        <Button
                                            variant="outlined"
                                            startIcon={<SaveIcon />}
                                            onClick={() => setSaveDialogOpen(true)}
                                            disabled={!gcode.trim()}
                                        >
                                            Save
                                        </Button>
                                    </Box>
                                </Paper>
                            </Grid>

                            {/* Right Panel - Saved Commands */}
                            <Grid item xs={12} md={4}>
                                <Paper sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                        <Typography variant="h6">Saved Commands</Typography>
                                        <IconButton onClick={loadSavedCommands} size="small">
                                            <RefreshIcon />
                                        </IconButton>
                                    </Box>

                                    <Box sx={{ flex: 1, overflow: 'auto' }}>
                                        {savedCommands.length === 0 ? (
                                            <Typography color="text.secondary" sx={{ textAlign: 'center', mt: 4 }}>
                                                No saved MDI commands.
                                                <br />
                                                Create and save commands to see them here.
                                            </Typography>
                                        ) : (
                                            <List dense>
                                                {savedCommands.map((command, index) => (
                                                    <React.Fragment key={command.name}>
                                                        <ListItemButton
                                                            onClick={() => handleLoad(command)}
                                                            sx={{
                                                                borderRadius: 1,
                                                                mb: 1,
                                                                border: editingCommand?.name === command.name
                                                                    ? `2px solid ${config.primaryColor}`
                                                                    : '1px solid transparent',
                                                                '&:hover': {
                                                                    backgroundColor: `${config.primaryColor}10`
                                                                }
                                                            }}
                                                        >
                                                            <ListItemText
                                                                primary={command.name}
                                                                secondary={
                                                                    <Box>
                                                                        {command.exposeAsAction && (
                                                                            <Typography variant="caption" color="primary" display="block">
                                                                                Category: {command.categoryName}
                                                                            </Typography>
                                                                        )}
                                                                        <Typography variant="caption" color="text.secondary">
                                                                            {command.data.split('\n')[0].substring(0, 40)}
                                                                            {command.data.length > 40 ? '...' : ''}
                                                                        </Typography>
                                                                    </Box>
                                                                }
                                                            />
                                                            <ListItemSecondaryAction>
                                                                <IconButton
                                                                    edge="end"
                                                                    onClick={(e) => {
                                                                        e.stopPropagation();
                                                                        handleEdit(command);
                                                                    }}
                                                                    size="small"
                                                                    sx={{ mr: 1 }}
                                                                >
                                                                    <EditIcon />
                                                                </IconButton>
                                                                <IconButton
                                                                    edge="end"
                                                                    onClick={(e) => {
                                                                        e.stopPropagation();
                                                                        handleDelete(command);
                                                                    }}
                                                                    size="small"
                                                                    color="error"
                                                                >
                                                                    <DeleteIcon />
                                                                </IconButton>
                                                            </ListItemSecondaryAction>
                                                        </ListItemButton>
                                                        {index < savedCommands.length - 1 && <Divider />}
                                                    </React.Fragment>
                                                ))}
                                            </List>
                                        )}
                                    </Box>
                                </Paper>
                            </Grid>
                        </Grid>

                        <SaveDialog
                            open={saveDialogOpen}
                            onClose={() => {
                                setSaveDialogOpen(false);
                                setEditingCommand(null);
                            }}
                            onSave={handleSave}
                            initialName={editingCommand?.name || ''}
                            initialCategoryName={editingCommand?.categoryName || ''}
                            initialExposeAsAction={editingCommand?.exposeAsAction || false}
                        />
                    </Box>
                );
            }}
        />
    );
}