import {
  ToggleOff as ToggleOffIcon,
  ToggleOn as ToggleOnIcon
} from '@mui/icons-material';
import {
  Box,
  IconButton,
  ListItem,
  Tooltip,
  Typography
} from '@mui/material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { OutputWithState } from '../../data/IOStateData';

interface OutputItemProps {
  output: OutputWithState;
  isActive: boolean;
  onToggle: (outputNumber: number, newState: boolean) => void;
}

export function OutputItem({ output, isActive, onToggle }: OutputItemProps) {
  const config = ConfigurationData.Instance;
  const displayText = isActive ? output.activeText : output.inactiveText;
  const activeColor = '#4caf50'; // Green color for active outputs

  return (
    <ListItem
      sx={{
        py: 0.75,
        px: 1.5,
        borderBottom: `1px solid ${config.borderColor}`,
        minHeight: 48,
        display: 'flex',
        alignItems: 'center'
      }}
    >
      <Box sx={{
        display: 'flex',
        alignItems: 'center',
        width: '100%',
        gap: 1
      }}>
        {/* Output Number in Solid Box */}
        <Box
          sx={{
            width: 28,
            height: 24,
            backgroundColor: isActive ? activeColor : config.borderColor,
            color: isActive ? 'white' : config.mutedTextColor,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: 1,
            fontSize: '0.75rem',
            fontWeight: 'bold',
            flexShrink: 0
          }}
        >
          {output.number}
        </Box>

        {/* Output Name */}
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography
            variant="body2"
            sx={{
              fontSize: '0.8rem',
              fontWeight: 500,
              color: config.darkTextColor,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
          >
            {output.name}
          </Typography>
        </Box>

        {/* Active/Inactive Status Text */}
        <Box sx={{
          minWidth: 80,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-end'
        }}>
          <Typography
            variant="caption"
            sx={{
              fontSize: '0.7rem',
              fontWeight: isActive ? 'bold' : 'normal',
              color: isActive ? activeColor : config.mutedTextColor,
              textAlign: 'right'
            }}
          >
            {displayText}
          </Typography>
        </Box>

        {/* Toggle Button */}
        <Box sx={{
          minWidth: 40,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-end'
        }}>
          <Tooltip title={`Turn ${isActive ? 'OFF' : 'ON'}`}>
            <IconButton
              size="small"
              onClick={() => onToggle(output.number, !isActive)}
              sx={{
                color: isActive ? activeColor : config.mutedTextColor,
                '&:hover': {
                  backgroundColor: isActive
                    ? `${activeColor}1A`
                    : `${config.mutedTextColor}1A`
                }
              }}
            >
              {isActive ? <ToggleOnIcon /> : <ToggleOffIcon />}
            </IconButton>
          </Tooltip>
        </Box>
      </Box>
    </ListItem>
  );
}