import { Box, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';

export function CoordinatesDisplay() {
    const [config] = useState(() => ConfigurationData.Instance);

    return (
        <ObserveMultiProperties
            listenTo={[
                {
                    object: MachineStateData.Instance,
                    properties: ['currentMachinePoint', 'currentWorkZero', 'currentToolOffsets']
                },
                {
                    object: ConfigurationState.Instance,
                    properties: ['currentFixture']
                }
            ]}
            control={() => {
                const machineState = MachineStateData.Instance;
                const currentFixture = ConfigurationState.Instance.currentFixture;

                const currentMachinePoint = machineState.currentMachinePoint;

                // Use CoordinateUtil for all coordinate transformations
                const workCoords = CoordinateUtil.toWorkZero(currentMachinePoint);
                const machineZeroCoords = CoordinateUtil.toMachineZero(currentMachinePoint);
                const machineHomeCoords = CoordinateUtil.toMachineHome(currentMachinePoint);
                const fixtureOffsetCoords = CoordinateUtil.toFixtureOffset(currentMachinePoint);

                const formatCoord = (value: number) => value.toFixed(3);

                const coordinateSectionStyle = {
                    mb: 2,
                    p: 1.5,
                    borderRadius: 1,
                    backgroundColor: config.lightBackgroundColor,
                    border: `1px solid ${config.borderColor}`
                };

                const coordinateRowStyle = {
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    mb: 0.5
                };

                return (
                    <Box sx={{ height: '100%', overflow: 'auto', p: 2 }}>
                        <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
                            Coordinates
                        </Typography>

                        {/* Work Zero */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: config.primaryColor }}>
                                Work Zero
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workCoords.x)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workCoords.y)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(workCoords.z)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* Machine Zero */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: config.primaryColor }}>
                                Machine Zero
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineZeroCoords.x)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineZeroCoords.y)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineZeroCoords.z)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* Machine Home */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: config.primaryColor }}>
                                Machine Home
                            </Typography>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">X:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeCoords.x)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Y:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeCoords.y)}
                                </Typography>
                            </Box>
                            <Box sx={coordinateRowStyle}>
                                <Typography variant="body2">Z:</Typography>
                                <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                    {formatCoord(machineHomeCoords.z)}
                                </Typography>
                            </Box>
                        </Box>

                        {/* From Current Fixture */}
                        <Box sx={coordinateSectionStyle}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1, color: config.primaryColor }}>
                                From Current Fixture
                                {currentFixture && (
                                    <Typography component="span" variant="caption" sx={{ ml: 1, color: config.darkTextColor }}>
                                        ({currentFixture.fixtureNumber})
                                    </Typography>
                                )}
                            </Typography>
                            {currentFixture ? (
                                <>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">X:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureOffsetCoords.x)}
                                        </Typography>
                                    </Box>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">Y:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureOffsetCoords.y)}
                                        </Typography>
                                    </Box>
                                    <Box sx={coordinateRowStyle}>
                                        <Typography variant="body2">Z:</Typography>
                                        <Typography variant="body2" sx={{ fontFamily: 'monospace', fontWeight: 'bold' }}>
                                            {formatCoord(fixtureOffsetCoords.z)}
                                        </Typography>
                                    </Box>
                                </>
                            ) : (
                                <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                                    No fixture selected
                                </Typography>
                            )}
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
